INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100101_001", "ヒヨリ", 1, "どんなに敵が大勢でも、みんなで\n力を合わせれば絶対大丈夫だよ！\nだから顔を上げてこう！\nごーごー！", "vo_empress_100101_001", 1, 1, 0, 5, "", 100101, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100101_002", "ヒヨリ", 1, "ううっ、何度も戦う相手もいるけど\nあたし、負けたりなんてしないよ！\n今回だってみんなや騎士くんがいる\nフルパワーでいくよーっ！", "vo_empress_100101_002", 2, 1, 0, 5, "", 100103, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100101_003", "ヒヨリ", 2, "うぅ…すごい力…！\n…でも、なんだか悲しそう\nこの人の気持ちを知りたい\nだからこそ…勝たなきゃ…！", "vo_empress_100101_003", 3, 1, 0, 5, "", 100103, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100101_004", "ヒヨリ", 3, "騎士くんの力があれば、\nあたしは絶対負けないよ！\nみんなが笑顔でいられるように\n一緒にがんばろう！", "vo_empress_100101_004", 4, 1, 100101, 5, "", 100102, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100201_001", "ユイ", 1, "わたしたちの世界のためにも\nこの世界のためにも、\n絶対に負けられない…！\nがんばろうね、騎士クン", "vo_empress_100201_001", 5, 1, 0, 5, "", 100203, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100201_002", "ユイ", 1, "みんな、怪我したらすぐに教えて！\n…もう誰も失いたくないの\nそのために修行もしたんだから…\n大丈夫、絶対なんとかしてみせる！", "vo_empress_100201_002", 6, 1, 0, 5, "", 100203, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100201_003", "ユイ", 2, "世界を『書き換え』するなんて…\nそんな未来、寂しいだけだよ…！\nお願い、これ以上みんなを\n傷つけないで…話を聞いて！", "vo_empress_100201_003", 7, 1, 0, 5, "", 100203, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100201_004", "ユイ", 3, "感じるよ、騎士クンの気持ち…\n抱きしめられてるみたいに\nあったかい…\nぜんぶ終わらせよう！", "vo_empress_100201_004", 8, 1, 100201, 5, "", 100202, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100301_001", "レイ", 1, "厳しい戦いになるだろうな\n安心してくれ、何があっても\nキミは守る。…いや、違うな\n一緒に、世界を守ろう", "vo_empress_100301_001", 9, 1, 0, 5, "", 100301, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100301_002", "レイ", 1, "手ごわい相手ばかりだな…\nだが引き下がるわけにはいかない\nこちらにだって譲れないものが\nあるんだ！", "vo_empress_100301_002", 10, 1, 0, 5, "", 100303, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100301_003", "レイ", 2, "くっ…なんて力だ…！\n防ぐだけで精一杯…だが、\n例え剣が折れたとしても、\n私は最後まで戦い続ける！", "vo_empress_100301_003", 11, 1, 0, 5, "", 100303, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100301_004", "レイ", 3, "感じるよ、キミからの愛\nこれがあれば、私はどんな\n敵にだって打ち勝てる！\n見せてやろう、一緒に！", "vo_empress_100301_004", 12, 1, 100301, 5, "", 100302, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100401_001", "ミソギ", 1, "ミソギとにいちゃんはこれからも\n世界中を冒険して、ワクワクする\nお宝をたくさん見つけるんだ！\nワルモノなんかに邪魔させないよ！", "vo_empress_100401_001", 13, 1, 0, 5, "", 100401, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100401_002", "ミソギ", 1, "わわ、なんかヤバそうな雰囲気…\nこういう時こそミソギの出番だね！\nとっておきのイタズラ決めて、\nピンチもひっくり返しちゃうよ！", "vo_empress_100401_002", 14, 1, 0, 5, "", 100401, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100401_003", "ミソギ", 2, "うぅ…あの悪者、すごい迫力だよ…\nもしミソギたちが負けちゃったら、\nミソギもにいちゃんもこの世界も…\n全部おしまい、なんだよね…？", "vo_empress_100401_003", 15, 1, 0, 5, "", 100403, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100401_004", "ミソギ", 3, "ミソギたちが世界を救っちゃったら\nきっとみんなびっくりするよね！\nどんな顔して驚いてくれるかな…\nにひひ、なんかワクワクしてきた！", "vo_empress_100401_004", 16, 1, 100401, 5, "", 100402, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100501_001", "マツリ", 1, "歴代オールヒーロー大進撃ッス～！\n自分は新世代のエースってとこッス\nかね？　さあ、ついてくるッス……\nあれ？　みんなどこ？　待って～", "vo_empress_100501_001", 17, 1, 0, 5, "", 100501, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100501_002", "マツリ", 1, "敵は圧倒的な力で、こっちを絶望\nさせる気ッスかね？　だとしたら\n大誤算ッスよ！　むしろ自分の\n正義の魂に火をつけたんスから！", "vo_empress_100501_002", 18, 1, 0, 5, "", 100501, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100501_003", "マツリ", 2, "足が……震えるッス……けど！\nこれは武者震いッス……！　だって\nヒーローは絶対に絶対にっ！\n敗北なんてしないんスから……っ！", "vo_empress_100501_003", 19, 1, 0, 5, "", 100503, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100501_004", "マツリ", 3, "さあ、手と手をつないで、\n二人で教えてやるッスよ！\nどんな物語でも、悪は必ずヒーロー\nに打ち倒されるってことを！", "vo_empress_100501_004", 20, 1, 100501, 5, "", 100502, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100601_001", "アカリ", 1, "ひゃぁんっ！\nもう、敵さんが脅かしてくるから\nアカリ、ヘンな声出ちゃいました…\nこういうの、よくないですよっ", "vo_empress_100601_001", 21, 1, 0, 5, "", 100603, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100601_002", "アカリ", 1, "アカリ、お兄ちゃんとシタイコトが\nまだまだいっぱいあるんです！\nだから、私たちの大事な世界も…\n本気で守り抜いてみせますっ！", "vo_empress_100601_002", 22, 1, 0, 5, "", 100601, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100601_003", "アカリ", 2, "うぅ…こんなに激しく攻められたら\nアカリ、もう壊れちゃいそうです…\nだけどまだまだ…戦えますっ！\nお兄ちゃんが一緒なんですからっ…", "vo_empress_100601_003", 23, 1, 0, 5, "", 100603, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100601_004", "アカリ", 3, "お兄ちゃんの愛を注いでもらって\nアカリ超絶パワーアップです！\nアカリらしく世界一かわいく、\n世界を救ってみせちゃいますよ！", "vo_empress_100601_004", 24, 1, 100601, 5, "", 100602, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100701_001", "ミヤコ", 1, "アイツらが野放しだと、ミヤコは\n安心してプリンを食べられないの\n今日のプリンと明日のプリンの\nためにも、絶対負けないの！", "vo_empress_100701_001", 25, 1, 0, 5, "", 100701, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100701_002", "ミヤコ", 1, "前はミヤコ、悪いヤツに捕まって\n消されそうになって怖かったの…\nでも今度は全然怖くないの！\nオマエが一緒なら平気なの！", "vo_empress_100701_002", 26, 1, 0, 5, "", 100702, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100701_003", "ミヤコ", 2, "むうぅ～っ、アイツしつこいの！\nこうなったら、オマエにも\nミヤコのプリン分けてやるの！\nダブルプリンパワーで頑張るの！", "vo_empress_100701_003", 27, 1, 0, 5, "", 100703, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100701_004", "ミヤコ", 3, "アイツはどんなに強くたって、\n独りぼっちのさびしいヤツなの\nでもオマエにはミヤコがいるの！\nミヤコたちなら絶対に勝てるの！", "vo_empress_100701_004", 28, 1, 100701, 5, "", 100702, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100801_001", "ユキ", 1, "相手が誰であれ、やることは同じ…\nそう…ボクの美しさを見せてあげる\nことさ！　予言しよう…絶世の美の\n前にはどんな敵もひれ伏すと、ね！", "vo_empress_100801_001", 29, 1, 0, 5, "", 100801, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100801_002", "ユキ", 1, "少し待っていてくれる？　メイクを\n直さないと。避けられない戦いなら\nせめて美しいボクと戦えることを\n彼らには誇りに思ってほしいからね", "vo_empress_100801_002", 30, 1, 0, 5, "", 100801, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100801_003", "ユキ", 2, "どうせ倒れるなら美しいままで散り\nたいな。ふふ、難しい望みかな…？\nそれでもボクは、最後まで美しく\nあがいてみせるよ、キミと一緒にね", "vo_empress_100801_003", 31, 1, 0, 5, "", 100801, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100801_004", "ユキ", 3, "ボクがいて、キミがいる。ボクたち\nが勝つのに、これ以上の理由はない\nよね。だって美しい者が勝つ未来の\nほうが、美しいエンディングだもの", "vo_empress_100801_004", 32, 1, 100801, 5, "", 100802, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100901_001", "アンナ", 1, "災厄の嵐が吹き荒れ、世界の命運は\n風前の灯が如く儚い。だが絶望には\nまだ早い！　希望はここに在り！\n灯火を掲げよう、盟友シグルドよ！", "vo_empress_100901_001", 33, 1, 0, 5, "", 100901, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100901_002", "アンナ", 1, "終焉の日、滅びの刻来たれり、か…\nだが、幾度も転生を繰り返しながら\n戦いつづけた我らの宿命を思えば、\nこの程度取るに足らない…はずだ！", "vo_empress_100901_002", 34, 1, 0, 5, "", 100903, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100901_003", "アンナ", 2, "くっ…なんという禍々しい魔力…！\nもはや世界の滅びも間近…しかし\n疾風の冥姫がここで退くわけには\nいかぬ！　しぶとく抗ってみせるぞ", "vo_empress_100901_003", 35, 1, 0, 5, "", 100903, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_100901_004", "アンナ", 3, "永遠の盟約で結ばれし魂の伴侶…\n世界を滅ぼさんとする災禍の剣も\nこの絆を断ち切ることはできない！\n覚悟するがいい、幻境竜后！！", "vo_empress_100901_004", 36, 1, 100901, 5, "", 100902, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101001_001", "マホ", 1, "【自警団】のギルドマスターとして\nしゃんとして恥ずかしない姿を\n見せなあきまへんなぁ…王子はん\nしゃなりしゃなり、いきまひょ！", "vo_empress_101001_001", 37, 1, 0, 5, "", 101001, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101001_002", "マホ", 1, "王子はん、服が破れてますえ？\nこれでよし…うん、完璧や♪\n戦いの中でも、王子はんには\n格好良う居てもらいたいさかいに♪", "vo_empress_101001_002", 38, 1, 0, 5, "", 101001, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101001_003", "マホ", 2, "幻境竜后…大層なお名前してはる\nお后さまが勝負を挑んできはるなら\nうちも、マホマホ王国の姫として…\n正々堂々受けて立ちますえ！", "vo_empress_101001_003", 39, 1, 0, 5, "", 101003, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101001_004", "マホ", 3, "強い愛で結ばれた王子と姫を\n引き裂くことは誰にもできまへん\n王子はん…ふたりで一緒に！\nハッピーエンドを迎えまひょ！", "vo_empress_101001_004", 40, 1, 101001, 5, "", 101002, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101101_001", "リノ", 1, "お兄ちゃんがいれば百人力士っ！\n妹パワーも全開でいきますよ～♪\nどんな敵でもドンドンこいですっ！\nあれ？　ちょっと違いました？", "vo_empress_101101_001", 41, 1, 0, 5, "", 101101, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101101_002", "リノ", 1, "これぞまさに『四面そば』…\n敵多すぎでもう大盛りですけど\n秘密結社の一員として、妹として\nこの世界の平和は守り通しますっ！", "vo_empress_101101_002", 42, 1, 0, 5, "", 101101, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101101_003", "リノ", 2, "あれが幻境竜后…不思議な服…\nじゃなくて、空気がピリピリです…\nちょっとだけ怖いけど…妹として\n絶対に降参なんてしませんよ！", "vo_empress_101101_003", 43, 1, 0, 5, "", 101103, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101101_004", "リノ", 3, "私、もう迷いません！\nお兄ちゃんと一緒なら\nどんな敵だって倒しちゃいます！\n妹のポテンシャルは無限大ですよ！", "vo_empress_101101_004", 44, 1, 101101, 5, "", 101102, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101201_001", "ハツネ", 1, "どんなに大変な時でもキミと一緒に\nず～っと乗り越えてきたんだもん！\nだからっ、今回もきっと大丈夫！\n私の魔法できらーん☆　だよっ！", "vo_empress_101201_001", 45, 1, 0, 5, "", 101201, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101201_002", "ハツネ", 1, "力を使いすぎると眠く…スヤァ…\nはっ、いけないいけない！\nキミ、私が寝ちゃったら起こして！\n…お、王子様のキスとかで…", "vo_empress_101201_002", 46, 1, 0, 5, "", 101202, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101201_003", "ハツネ", 2, "も～！　容赦なさすぎだよぉ！\nそっ、それにさっきまでの戦いの\nせいで、ね、眠気がぁ～っ…\nハ、ハツネちゃん、ピ～ンチ…", "vo_empress_101201_003", 47, 1, 0, 5, "", 101203, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101201_004", "ハツネ", 3, "幻境竜后さんがどんなに強くても\n今のハツネちゃんは無敵なのだ～！\n大好きなキミと！　シオリンと！\nみんながいる世界を守っちゃうよ！", "vo_empress_101201_004", 48, 1, 101201, 5, "", 101202, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101301_001", "ナナカ", 1, "この世界にはね、たくさんの人の\n『好き』が詰まってるんだよ\nそれをぶち壊すなんて鬼畜の所業\nナナカちゃんが許しはしないぜ！", "vo_empress_101301_001", 49, 1, 0, 5, "", 101301, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101301_002", "ナナカ", 1, "見るからにヤバい奴らが勢ぞろい！\nでもみんなの世界が狙われてんのに\n日和ってる奴いる？いねえよなぁ！\n全員ぶっ飛ばして世界を救うぞ！！", "vo_empress_101301_002", 50, 1, 0, 5, "", 101301, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101301_003", "ナナカ", 2, "あとはラスボスを倒せば勝利ッ！\n第３部完！　…とはいかない感じ？\nていうか逆にピンチな気配？\nどっどうしよう、どうすれば！？", "vo_empress_101301_003", 51, 1, 0, 5, "", 101303, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101301_004", "ナナカ", 3, "幻境竜后…確かに強敵だったね\nでも今はもう負ける気がしないかな\nだって私は、ただのナナカじゃない\n超ナナカちゃんだから…！", "vo_empress_101301_004", 52, 1, 101301, 5, "", 101302, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101401_001", "カスミ", 1, "あちらにもなかなかの陰謀家がいる\nようだね。彼女らの最大の誤算は\nここに希代の名探偵がいることさ！\nさあ助手くん。真実を勝ち取ろう！", "vo_empress_101401_001", 53, 1, 0, 5, "", 101401, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101401_002", "カスミ", 1, "仕方ない、こうなったら奥の手だ\nミスティ！　セオリー！　…って\nこらぁっ！　変身の最中は待って\nくれるのがお約束だよ！？", "vo_empress_101401_002", 54, 1, 0, 5, "", 101401, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101401_003", "カスミ", 2, "なっ…なんだい、この悪寒は…\n触れてはならない何か…いいや！\n名探偵たるもの巨悪に恐れをなす\nわけにはいかない。絶対に…！", "vo_empress_101401_003", 55, 1, 0, 5, "", 101403, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101401_004", "カスミ", 3, "どんな哀しみでさえ、道理を穢す\n理由にしてはならない。さあ、\nお縄につくんだ。史上最大の迷宮\n事件…終わらせるのは…この私だ！", "vo_empress_101401_004", 56, 1, 101401, 5, "", 101402, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101501_001", "ミサト", 1, "先生は…ううん、先生たちは。\n絶対に負けません。みんなに傷一つ\nつけさせたりはしないわ…！", "vo_empress_101501_001", 57, 1, 0, 5, "", 101501, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101501_002", "ミサト", 1, "とっても強大な敵ばかりね…\nでも、大丈夫。焦らず落ち着いて\n戦いましょう。先生がついてるわ\n長引いても、あきらめないで…！", "vo_empress_101501_002", 58, 1, 0, 5, "", 101501, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101501_003", "ミサト", 2, "幻境竜后さんの力…すごいわ…\nううん、怖がってる暇なんてないの\n森のみんなを守るためにも…！\n好き勝手したら「めっ」ですからね", "vo_empress_101501_003", 59, 1, 0, 5, "", 101501, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101501_004", "ミサト", 3, "あなたと一緒なら\n負けたりなんか絶対にしないわ\n最後の一撃まで、\nがんばりましょうね♪", "vo_empress_101501_004", 60, 1, 101501, 5, "", 101502, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101601_001", "スズナ", 1, "ツヨそーな敵ばっかりで\nテン下げってカンジだけど\nとりま、うちとヒデサイが\n一緒なら乗り越えられるっしょ！", "vo_empress_101601_001", 61, 1, 0, 5, "", 101601, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101601_002", "スズナ", 1, "あっ、まってヒデサイ\nマントずれてるから直してあげる\n…よし！　こーゆう時こそ\nおしゃれでテン上げしなきゃね♪", "vo_empress_101601_002", 62, 1, 0, 5, "", 101601, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101601_003", "スズナ", 2, "おにヤバすぎて超わろ～…でもでも\nどうにかやるしかないっしょ～\n勝利のランウェイ遠すぎだけど\nうちら諦めんのはダメだよね～！", "vo_empress_101601_003", 63, 1, 0, 5, "", 101601, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101601_004", "スズナ", 3, "アオハルでバイブス爆上げ♪\n今のうちらは、ムテキだよ～\nハッピーで、もにカワな未来だって\n一緒にゲットするしかないっしょ♪", "vo_empress_101601_004", 64, 1, 101601, 5, "", 101602, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101701_001", "カオリ", 1, "歌ったり踊ったり、\nキミと一緒にやりたいことが\nばんないあるからね～！\n絶対に負けられないさ～！", "vo_empress_101701_001", 65, 1, 0, 5, "", 101701, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101701_002", "カオリ", 1, "ううっ強そうな敵ばっかりさ～！\n長丁場の戦いにはやっぱりこれよ～\nサーターアンダギー！\n栄養付けて平和を守るさ～♪", "vo_empress_101701_002", 66, 1, 0, 5, "", 101701, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101701_003", "カオリ", 2, "うぅ～、幻境竜后、でーじ強いね～\n私たちも引き下がる気はないよ～！\nどんなに時間がかかっても、絶対に\n諦めたりしないさ～！　だよね～？", "vo_empress_101701_003", 67, 1, 0, 5, "", 101703, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101701_004", "カオリ", 3, "キミのくれた情熱が、\n私の中で熱く燃え滾ってるよ！\n最高の一撃、キミに見せるさ～！", "vo_empress_101701_004", 68, 1, 101701, 5, "", 101702, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101801_001", "イオ", 1, "学校生活の邪魔はさせないわ\nだって私、みんなの先生だもの\n明日の授業も世界のことも\n全部守ってみせるんだから！", "vo_empress_101801_001", 69, 1, 0, 5, "", 101801, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101801_002", "イオ", 1, "やん！　なんて手ごわい人たちなの\nでも諦めないわ。難しい問題だって\n落ち着いてやればちゃんと解けるの\n戦いも同じよ…いきましょう！", "vo_empress_101801_002", 70, 1, 0, 5, "", 101801, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101801_003", "イオ", 2, "これが、幻境竜后さんの力…圧倒\nされちゃいそう。でも、怖がってる\n場合じゃないわ。先生は絶対に、\nここから退かないわ！", "vo_empress_101801_003", 71, 1, 0, 5, "", 101803, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_101801_004", "イオ", 3, "二人の絆があれば、\n怖いものなんてないわ\n先生と力を合わせて─\nいきましょう♪", "vo_empress_101801_004", 72, 1, 101801, 5, "", 101802, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102001_001", "ミミ", 1, "す、すごく強そうな人がいっぱい…\nミミ、怖くてぶるぶるしちゃうけど\nでも泣いちゃったりはしないよっ\nおにいちゃんがいっしょだもん…！", "vo_empress_102001_001", 73, 1, 0, 5, "", 102003, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102001_002", "ミミ", 1, "プチグリフォンさんもハナちゃんも\nみゅ～ちゃんも…きっとみんな、\nミミのこと応援してくれてるよね\nだからミミも、がんばるよっ…！", "vo_empress_102001_002", 74, 1, 0, 5, "", 102003, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102001_003", "ミミ", 2, "あ、あの竜の人…本気になったら、\nすごく強そうだよ…！このままじゃ\nみんなもミミたちも負けちゃう…？\nやだ、ミミそんなのいやだよっ…", "vo_empress_102001_003", 75, 1, 0, 5, "", 102003, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102001_004", "ミミ", 3, "おにいちゃんがくれた元気、\n今度はミミたちから届けようね\nもう大丈夫、心配しないでって…\n世界中の、大切なお友だちに…！", "vo_empress_102001_004", 76, 1, 102001, 5, "", 102002, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102101_001", "クルミ", 1, "怖い人たちがいっぱいですぅ…！\n…でも、みんな頑張ってる…私も\nベルルちゃんみたいに勇気を出して\n…祝福の音を鳴らしましょう！", "vo_empress_102101_001", 77, 1, 0, 5, "", 102101, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102101_002", "クルミ", 1, "お兄ちゃん、私、がんばりますぅ\n『ロスト』したお父さんたちの\nためにも…！　怖い時こそ前を見て\n戦ってみせますからっ…！", "vo_empress_102101_002", 78, 1, 0, 5, "", 102101, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102101_003", "クルミ", 2, "っ…すごい迫力ですぅ…！\nでも…絶望は必ず乗り越えられる\n胸の中の、希望の音色を信じて…\n逃げたりなんか、しませんよぅ…っ", "vo_empress_102101_003", 79, 1, 0, 5, "", 102101, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102101_004", "クルミ", 3, "みんなに勇気を与えるために\n主役にも英雄にもなってみせますぅ\nお兄ちゃんがいてくれるなら\n私はなんでもできるんです…！", "vo_empress_102101_004", 80, 1, 102101, 5, "", 102102, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102201_001", "ヨリ", 1, "こ、これくらいの敵、問題ないわ！\nほんとはちょっと怖いけど…\nゲームの世界を救うことくらい\nこっちは慣れっこなんだから…！", "vo_empress_102201_001", 81, 1, 0, 5, "", 102201, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102201_002", "ヨリ", 1, "ここで私たちが負けたら、\n世界が終わっちゃうなんて…\n絶対に認めるわけにはいかないわ！\nアンタも覚悟決めなさいよっ！", "vo_empress_102201_002", 82, 1, 0, 5, "", 102201, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102201_003", "ヨリ", 2, "ここからが本当の戦いってこと？\nならもう、とことんやってやるわ！\nゲーマーってのは、敵が手強いほど\n燃えてくる生き物なのよ！", "vo_empress_102201_003", 83, 1, 0, 5, "", 102203, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102201_004", "ヨリ", 3, "絶対に帰りたい理由ができた…\nそう思うだけで、いくらでも力が\n湧いてくるの。これならもう、\n文句なしの勝ち確よねっ！", "vo_empress_102201_004", 84, 1, 102201, 5, "", 102202, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102301_001", "アヤネ", 1, "私もみんなと一緒に戦うよ！\n悪い人たちはフルスイングで\nあっという間に倒しちゃうから！\n『おうっ！　全員かかってこい！』", "vo_empress_102301_001", 85, 1, 0, 5, "", 102301, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102301_002", "アヤネ", 1, "本当はちょっとだけ怖いけど…\nぷうきちもお兄ちゃんも一緒だもん\n力を合わせて世界を守っちゃうよ\n絶対に負けないんだから！", "vo_empress_102301_002", 86, 1, 0, 5, "", 102303, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102301_003", "アヤネ", 2, "ううっあの人、すごく怖いけど\n逃げないよ、戦うって決めたもん\nね、お兄ちゃん、ぷうきち！\n『ここが踏ん張りどころだぞ！』", "vo_empress_102301_003", 87, 1, 0, 5, "", 102303, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102301_004", "アヤネ", 3, "お兄ちゃんが約束してくれたもん\n今の私ならどんな悪いやつにも\n負けないよ！　宇宙人でもなんでも\n一撃で追い返しちゃうんだから♪", "vo_empress_102301_004", 88, 1, 102301, 5, "", 102302, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102501_001", "スズメ", 1, "大変なことになっちゃいましたね…\nで、でも怖がっていられません！\nお嬢さまのことも、あなたのことも\n私が精一杯お支えします！", "vo_empress_102501_001", 89, 1, 0, 5, "", 102503, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102501_002", "スズメ", 1, "世界の命運がかかってますから\nドジなんてしてられません！\n…って、ああっ！　言ったそばから\nまた魔法が暴走しちゃいましたっ！", "vo_empress_102501_002", 90, 1, 0, 5, "", 102503, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102501_003", "スズメ", 2, "す、すごい力です…！\nでもお嬢さまや大切な人をおいて\n逃げるわけにはいきません！\nどこまでもお供します…！", "vo_empress_102501_003", 91, 1, 0, 5, "", 102503, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102501_004", "スズメ", 3, "大切な人と力を合わせれば、\nドジな私でも世界を救えるんです！\n世界規模…いえ、宇宙規模の大掃除\n始めちゃいますよ～っ！", "vo_empress_102501_004", 92, 1, 102501, 5, "", 102502, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102601_001", "リン", 1, "ええー？　こんだけ人数いるならさ\n一人ぐらいいなくても…\n…って空気じゃないわけね\nはいはい、あたしも働きますよー", "vo_empress_102601_001", 93, 1, 0, 5, "", 102603, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102601_002", "リン", 1, "うぅ…あんなのもうバグでしょ！？\nこんな無理ゲーに参戦したんだもん\n終わったらしばらく働かないから！\nダラダラゴロゴロするからね～！", "vo_empress_102601_002", 94, 1, 0, 5, "", 102603, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102601_003", "リン", 2, "見てよあのビジュアルさー\nまさにラスボスって感じじゃん…\nでも、どんなゲームでもボスは\n倒せるわけだし…はぁ、やるかー", "vo_empress_102601_003", 95, 1, 0, 5, "", 102603, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102601_004", "リン", 3, "ここまで来たら後には退けないし\n正真正銘のラスボス戦ってんなら\nあたしも─気合い入れて\n少しぐらいイイとこ見せないとね！", "vo_empress_102601_004", 96, 1, 102601, 5, "", 102602, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102701_001", "エリコ", 1, "有象無象のクズ虫が、私たちの\n幸せを阻もうとしているようですね\nあぁ、なんて忌々しいのでしょう…\n残らずすり潰しますわ、クスクス…", "vo_empress_102701_001", 97, 1, 0, 5, "", 102701, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102701_002", "エリコ", 1, "クスクス…あら、失礼しましたわ\nこの連中を駆逐すれば、私たちの\n絆はより強く…そんな想像をしたら\n思わず…クスクスクス、クスクス", "vo_empress_102701_002", 98, 1, 0, 5, "", 102701, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102701_003", "エリコ", 2, "あの女…下らない言葉であなた様を\n誑かそうとしたとか。万死に値する\n罪…身の程を思い知らせてやるまで\n決して退きはしませんわ…", "vo_empress_102701_003", 99, 1, 0, 5, "", 102703, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102701_004", "エリコ", 3, "『壊し屋』と呼ばれる私ですが…\n今はこの力、創るために振るいます\nあなた様との愛、未来…\nクスクス…さあ参りましょう…♪", "vo_empress_102701_004", 100, 1, 102701, 5, "", 102702, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102801_001", "サレン", 1, "しっかり頭数揃えてきたわね…\nでもこの程度の力に屈するような\nあたしたちじゃないんだから\nあんたも、サポート頼んだわよ！", "vo_empress_102801_001", 101, 1, 0, 5, "", 102801, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (10000, "vo_empress_102801_002", "サレン", 4002, "ちょっと！　なんか向こうに\n教育に悪そうなのがいるんだけど！\nあいつは子どもたちの目に入る前に\nあたしたちで倒すわよ。いい？", "vo_empress_102801_002", 102, 1, 0, 3, 1, 102801, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102801_003", "サレン", 2, "もう、強すぎて参っちゃうわね…\nでも諦めるわけにはいかないわ\nこっちだって守らなきゃいけない\nものがたくさんあるんだから！", "vo_empress_102801_003", 103, 1, 0, 5, "", 102803, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102801_004", "サレン", 3, "いつも以上に負ける気がしないわ\nこれもあんたと気持ちが通じた\nおかげね。あんたが側にいる限り、\nあたしはずっと無敵なんだから！", "vo_empress_102801_004", 104, 1, 102801, 5, "", 102802, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102901_001", "ノゾミ", 1, "この世界が終わっちゃうって…\nアイドル活動も卒業ってコト！？\nファンのみんなが黙ってないよ！\nもちろん私だって…！", "vo_empress_102901_001", 105, 1, 0, 5, "", 102903, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102901_002", "ノゾミ", 1, "どんな強い敵にだって屈しない…\n歌って踊って戦うアイドルになる！\nあの日に誓った願い、私の希望！\n今こそ、果たして見せるんだから！", "vo_empress_102901_002", 106, 1, 0, 5, "", 102903, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102901_003", "ノゾミ", 2, "幻境竜后…ダンスも歌も、あなたに\nとって価値はないかもしれないけど\n私はこのステージから逃げたり\nなんてしない！　アイドルとして！", "vo_empress_102901_003", 107, 1, 0, 5, "", 102903, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_102901_004", "ノゾミ", 3, "星を書き換えるなんてすごい発想…\nプロデューサーとか向いてるかも？\nって、今はそんな場合じゃないか！\n覚悟してよね、幻境竜后！", "vo_empress_102901_004", 108, 1, 102901, 5, "", 102901, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103001_001", "ニノン", 1, "ショーグンの天下統一を阻む者は\n誰であろうと許しまセン！\nショーグン！　ここはチューシン\nニノンにお任せアーレー！", "vo_empress_103001_001", 109, 1, 0, 5, "", 103001, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103001_002", "ニノン", 1, "むむむ…待ち受けているのは強敵\nばかり…それでも退きまセン！\n超烈火之紅蓮旋風で、\nまとめて討ち取ってみせまショウ！", "vo_empress_103001_002", 110, 1, 0, 5, "", 103001, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103001_003", "ニノン", 2, "な、なんて強さ…このままでは、\nワタシたちは負けてしまいます…\n…いいえ。いいえ！　ショーグンの\nためにも、諦めることなど…っ！", "vo_empress_103001_003", 111, 1, 0, 5, "", 103003, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103001_004", "ニノン", 3, "感じマス、ショーグンの愛を…！\n今ならどんな敵が来ても、\nカッサイ、ボンサイ、\nオチャノコサイサイデース！", "vo_empress_103001_004", 112, 1, 103001, 5, "", 103002, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103101_001", "シノブ", 1, "この世界が、明日を迎えることなく\n滅んでしまうかもしれない…\n運命の岐路が、目の前にあります\n抗えるのは、私たちだけです…！", "vo_empress_103101_001", 113, 1, 0, 5, "", 103101, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103101_002", "シノブ", 1, "何よりも色濃い死の気配が、\n世界に満ちていくのを感じます\nでも、倒れるわけにはいきません\n最後まで戦いましょう、全力で", "vo_empress_103101_002", 114, 1, 0, 5, "", 103101, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103101_003", "シノブ", 2, "これほどまでに強大な力なんて…\n占いも、未来は滅びの闇に覆われ\nつつある、と出ています…それでも\n希望を手放すわけには…！", "vo_empress_103101_003", 115, 1, 0, 5, "", 103103, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103101_004", "シノブ", 3, "命ある者にとって、死の運命は\n決して避けられないもの…\nでも、今この時ではないはずです\n戦いましょう、未来のために…！", "vo_empress_103101_004", 116, 1, 103101, 5, "", 103101, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103201_001", "アキノ", 1, "これ以上の狼藉は許しません！\nウィスタリア家の名に懸けて、\nこの世界の人々を守ります…必ずや\n貴人としての役目を果たしますわ！", "vo_empress_103201_001", 117, 1, 0, 5, "", 103201, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103201_002", "アキノ", 1, "互いを利するウィンウィンの関係\nそれが商売の鉄則です。力を振るい\n一方的に望みを押し付けるなんて、\n倒産まっしぐらですわよっ！", "vo_empress_103201_002", 118, 1, 0, 5, "", 103201, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103201_003", "アキノ", 2, "幻境竜后…すさまじい力ですわね\n世界を意のままにするという野望も\n決して絵空事ではないのでしょう…\nそれでも私は…諦めませんわよ！", "vo_empress_103201_003", 119, 1, 0, 5, "", 103203, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103201_004", "アキノ", 3, "人々を守ることが力ある者の務め…\nそしてあなたさまと共に生きること\nそれが私の務めであり願いですわ！\nこの想いは、止まりませんわよ！", "vo_empress_103201_004", 120, 1, 103201, 5, "", 103202, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103301_001", "マヒル", 1, "こんな舞台で漫才したって\nみんなもお天道さんもどんよりだべ\n安心して笑ってられる世界を\nオラたちで取り戻すど！　おー！", "vo_empress_103301_001", 121, 1, 0, 5, "", 103301, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103301_002", "マヒル", 1, "お、おっかねぇ連中だ…！\nでも…スベっちまう怖さに比べりゃ\nマシだべな！　あははっ！\nみんなの笑顔は、オラが守るべ！", "vo_empress_103301_002", 122, 1, 0, 5, "", 103301, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103301_003", "マヒル", 2, "あの子、芸人として光りそうだべな\n幻境竜后なんて仰々しい名前も…\nノーヴィジョンズノープロブレム！\n…あたた！　激しいツッコミだべ！", "vo_empress_103301_003", 123, 1, 0, 5, "", 103303, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103301_004", "マヒル", 3, "逆境も笑顔で切り開く…\nあんちゃんと一緒なら\nできる気がすんだ\nオラたちの芸人魂、見せてやるべ！", "vo_empress_103301_004", 124, 1, 103301, 5, "", 103302, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103401_001", "ユカリ", 1, "元…ううん、正しき聖騎士として\nここでやらなきゃいつやるのよ…！\n必ずみんなを守りきってみせるわ\n怪我をした人は私のところへ！", "vo_empress_103401_001", 125, 1, 0, 5, "", 103401, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103401_002", "ユカリ", 1, "…んぐっ…ごくっ…ぷは～っ♪\nよぉし気合十分らわ～っ！\nこら～幻境竜后～っ！　隠れて\nないでかかってきなさ～い！", "vo_empress_103401_002", 126, 1, 0, 5, "", 103401, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103401_003", "ユカリ", 2, "ひっく…ふぇ？　な、なに……？\nと、とっても大きいのが見えりゅ…\n…なっ、なによこれえぇぇ！\nこ、これが幻境竜后の姿なのぉ～っ", "vo_empress_103401_003", 127, 1, 0, 5, "", 103403, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103401_004", "ユカリ", 3, "私は無敵らのよ～♪　この世界と\nキミと築く\n素敵な未来のために…幻境竜后！\nぶっとばしてやるわぁ～っ！", "vo_empress_103401_004", 128, 1, 103401, 5, "", 103402, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103601_001", "キョウカ", 1, "ここで私たちが諦めたら、このまま\n世界が終わっちゃう！　そんなの\n絶対ダメです！　負けられません！\n私たちで全部退治しちゃいますよ！", "vo_empress_103601_001", 129, 1, 0, 5, "", 103603, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103601_002", "キョウカ", 1, "うぅ、ふしんしゃがいっぱいです！\n…でも、このくらいへっちゃらです\nお母さんが心配する前に、早く\n片付けておうちに帰りましょう！", "vo_empress_103601_002", 130, 1, 0, 5, "", 103603, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103601_003", "キョウカ", 2, "あれが私たちの敵、幻境竜后…\nほ、本当に勝てるんでしょうか…？\n立ってるだけで体が震えて…でも、\n弱気になっちゃダメですよねっ…！", "vo_empress_103601_003", 131, 1, 0, 5, "", 103601, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103601_004", "キョウカ", 3, "正直に言うと…まだ少し怖いです\n我慢したって怖くて体が震えます\nでも、あなたがいてくれるから…\n勇気だって同じくらい湧いてきます", "vo_empress_103601_004", 132, 1, 103601, 5, "", 103602, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103701_001", "トモ", 1, "滅ぼすための力に、守るための力が\n屈するわけにはいかないよ。\nこの剣の誇りに賭けて、必ず止める\nさあ、来い！　ミクマ流が相手だ！", "vo_empress_103701_001", 133, 1, 0, 5, "", 103701, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103701_002", "トモ", 1, "追いかけっこでもしようか\n鬼さんこちら♪　…って、まだ\n来るの！？　不意打ちされる側に\nなるのは趣味じゃないんだけどな！", "vo_empress_103701_002", 134, 1, 0, 5, "", 103701, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103701_003", "トモ", 2, "踏み込めない…踏み込む隙がない…\n向きあってるだけで精一杯なんて…\nで、でも…こんなところで\n剣を捨てるわけにはっ…！", "vo_empress_103701_003", 135, 1, 0, 5, "", 103701, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103701_004", "トモ", 3, "勝機は私の中にあったんだ…！\nあなたとの、\n一番強くて絶対に消えない絆\nそれが、あいつを倒す力をくれる！", "vo_empress_103701_004", 136, 1, 103701, 5, "", 103702, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103801_001", "シオリ", 1, "手ごわい相手ですね…\nでも、不思議と怖くありません\nあなたと力を合わせれば\n何とかなるって信じていますから", "vo_empress_103801_001", 137, 1, 0, 5, "", 103801, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103801_002", "シオリ", 1, "あなたの応援で、私の胸に\n愛と希望が満ち溢れています…\n今こそ魔法狩人ピュアリー★シオリ\nに大変身する時なのかも…？", "vo_empress_103801_002", 138, 1, 0, 5, "", 103801, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103801_003", "シオリ", 2, "とてつもない力ですね…\nでも、諦めたくありません\n何度だって立ち上がってみせます\n今までと同じように…！", "vo_empress_103801_003", 139, 1, 0, 5, "", 103803, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_103801_004", "シオリ", 3, "今の私に怖いものなんてありません\nあなたとの愛の力がありますから♪\n…少し舞い上がり過ぎですかね？\nふふ、気を引き締めてがんばります", "vo_empress_103801_004", 140, 1, 103801, 5, "", 103802, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104001_001", "アオイ", 1, "進んで目立ちたくはないですけど…\nと、ともっ…友達を守るためなら！\nＢＢ団として、勇気を振り絞って…\n団長さんと一緒に戦います！", "vo_empress_104001_001", 141, 1, 0, 5, "", 104001, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104001_002", "アオイ", 1, "いいい、一緒に戦う仲間がこんなに\nいてくれるなんて、こ、心強いの\n助太郎～っ！　私も末席で参加し…\nじゃなくてっ！　全力で戦います！", "vo_empress_104001_002", 142, 1, 0, 5, "", 104002, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104001_003", "アオイ", 2, "ううっ、手も足も声も震えてます…\nで、でも逃げも隠れもしませんよっ\n逃げたらぼっちが廃ります！", "vo_empress_104001_003", 143, 1, 0, 5, "", 104003, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104001_004", "アオイ", 3, "私はひとりぼっちじゃない…\n団長さんと繋がった絆があるから\nどんな敵だって怖くないですっ！\n行きましょう、団長さんっ！", "vo_empress_104001_004", 144, 1, 104001, 5, "", 104002, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104201_001", "チカ", 1, "やめてくれる気はなさそうです\nそれなら私も、絶対にここを\n動きはしません…！　だって\n私は……ワガママですからっ！", "vo_empress_104201_001", 145, 1, 0, 5, "", 104203, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104201_002", "チカ", 1, "私の唱喚術は人を守るためのもの…\nこの世界の森羅万象を護るための\nもの。今こそ、声の限り歌います\nこの子たちと、あなたと共に！", "vo_empress_104201_002", 146, 1, 0, 5, "", 104201, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104201_003", "チカ", 2, "精霊たちが震えてる…今までの\n敵とは訳が違うってことですよね…\n私もここに立っているのが精一杯…\n怖いけど…でも！　退きません…！", "vo_empress_104201_003", 147, 1, 0, 5, "", 104203, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104201_004", "チカ", 3, "今なら歌える気がします。ずっと\n探していた、誰かの心を震わせる歌\n幻境竜后…孤独なあなたの心にも\n私たちの歌が届くように…！", "vo_empress_104201_004", 148, 1, 104201, 5, "", 104201, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104301_001", "マコト", 1, "敵さんがどんだけ強くったって\n後には退けねぇんだ！　そうだろ、\nさぁ、覚悟しやがれよ！", "vo_empress_104301_001", 149, 1, 0, 5, "", 104301, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104301_002", "マコト", 1, "くっ、敵の連中、ずいぶんな戦力\n揃えてきやがった。けど、\n数でも気合でも負けやしねぇ！\nあたしが嚙み砕いてやる！", "vo_empress_104301_002", 150, 1, 0, 5, "", 104301, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104301_003", "マコト", 2, "幻境竜后とやら…マジで\n洒落になんねえな。だからって\n引き下がるわけにゃいかねえ！\n持ちこたえてやるぜ！", "vo_empress_104301_003", 151, 1, 0, 5, "", 104303, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104301_004", "マコト", 3, "どんな強い敵でも\n恐れる必要なんてないよな\nさあ、いっしょに─最大パワーで\nブチのめしてやろうぜっ！", "vo_empress_104301_004", 152, 1, 104301, 5, "", 104302, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104401_001", "イリヤ", 1, "ここはいずれわらわが支配する世界\nつまり、わが領地に等しきもの…\n奴らのような不届き者の蛮行、\n見過ごすわけにはいかぬわ！", "vo_empress_104401_001", 153, 1, 0, 5, "", 104401, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104401_002", "イリヤ", 1, "厳しい戦いになりそうじゃな…\nお主もわらわから離れるでないぞ\nも、もちろん、大人の姿を保つのに\n都合がいいからというだけじゃ！", "vo_empress_104401_002", 154, 1, 0, 5, "", 104401, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104401_003", "イリヤ", 2, "何とも恐ろしく禍々しい力じゃ…\nだが、我が意志は決して挫けぬ\n高貴なる吸血鬼の誇りに懸けて、\n最後まで戦い抜いてみせようぞ", "vo_empress_104401_003", 155, 1, 0, 5, "", 104401, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104401_004", "イリヤ", 3, "己が誰を敵に回したのかを、\n骨の髄まで知らしめてやろうぞ\nここにいるのは固き絆で結ばれし\n伝説の吸血鬼とその眷属じゃ！", "vo_empress_104401_004", 156, 1, 104401, 5, "", 104401, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104501_001", "クウカ", 1, "とっても強そうな敵ですっ…\n当然、攻撃も強烈になるはず…\nドＳさん、ここはどうかクウカに、\n先頭をお任せください！　ぐふふ♪", "vo_empress_104501_001", 157, 1, 0, 5, "", 104501, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104501_002", "クウカ", 1, "安心してドＳさんに虐げてもらう\nためにもクウカは負けられませんっ\nこの世界で一番のドＭとして、\n全力で責められに行ってきますっ！", "vo_empress_104501_002", 158, 1, 0, 5, "", 104501, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104501_003", "クウカ", 2, "ううっ、刺激が強すぎますよ…っ\nだけど、ドＭのプライドにかけて\nここで退くわけにはいきませんっ！\nドＳさんのこと、守り抜きます…っ", "vo_empress_104501_003", 159, 1, 0, 5, "", 104503, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104501_004", "クウカ", 3, "その視線は、『全部終わったらたっ\nぷり調教してやるからな』という\n意味ですね！　ぐふふっ…♪　負け\nられない理由がまた一つできました", "vo_empress_104501_004", 160, 1, 104501, 5, "", 104502, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104601_001", "タマキ", 1, "強そうなやつらが目白押しにゃ～\n短期戦でどうにかならないなら…\n長丁場に向けて、特別価格の\nたい焼きはいかがかにゃ～？", "vo_empress_104601_001", 161, 1, 0, 5, "", 104601, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104601_002", "タマキ", 1, "ファントムキャッツは\n狙った獲物を逃がさないにゃ！\nあたしたちの未来を手に入れるまで\nとことんやってやるにゃ～！", "vo_empress_104601_002", 162, 1, 0, 5, "", 104601, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104601_003", "タマキ", 2, "にゃにゃっ、これが幻境竜后…\nとんでもない力だにゃ\nでも、ここで逃げたらファントム\nキャッツの名が廃るにゃ～！", "vo_empress_104601_003", 163, 1, 0, 5, "", 104603, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104601_004", "タマキ", 3, "ファントムキャッツにかかれば\nどんなに強い悪党でも\n滅びる運命にゃ！\nとっておきの一撃、キメるにゃ～！", "vo_empress_104601_004", 164, 1, 104601, 5, "", 104602, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104701_001", "ジュン", 1, "全軍展開！　敵の一体たりとも\nこの先へは進ませるな\n苦しいときは、私の背中を見るんだ\n我々は決して折れはしない！", "vo_empress_104701_001", 165, 1, 0, 5, "", 104701, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104701_002", "ジュン", 1, "少年…\n最前線は危険だが、下がるつもりは\nないのか？　ふふ、やはり強情だな\nならば、私の隣を絶対に離れるな", "vo_empress_104701_002", 166, 1, 0, 5, "", 104701, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104701_003", "ジュン", 2, "な…なんだ…この冷たい闘気は…！\nみんな、いったん退がれ！\n安心しろ、ここは私が防ぎきる\n…たとえ…この身に代えても", "vo_empress_104701_003", 167, 1, 0, 5, "", 104701, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104701_004", "ジュン", 3, "幻境竜后、貴様は絶対に勝てないよ\n自分の身以上に、大切な誰かを\n守りたいという、人間の持つ尊い\n想いを、知ることのない貴様は…！", "vo_empress_104701_004", 168, 1, 104701, 5, "", 104701, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104801_001", "ミフユ", 1, "バイト仲間とこの世界のみんなを\n守るために！　私たちのやるべき\nことはただ一つ！　いいわね？\n─最高の効率で倒すわよ！", "vo_empress_104801_001", 169, 1, 0, 5, "", 104801, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104801_002", "ミフユ", 1, "相手も数が多いし、短期決戦とは\nいかないわね…って！　早く\n勝たなきゃバイトに遅刻しちゃう\nもっと効率アップしていくわよ！", "vo_empress_104801_002", 170, 1, 0, 5, "", 104801, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104801_003", "ミフユ", 2, "幻境竜后……本当に圧倒的な力ね\nだからってそう簡単に諦められる\nわけはないわよね。たとえそれが\n非効率的な判断だとしても……！", "vo_empress_104801_003", 171, 1, 0, 5, "", 104803, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104801_004", "ミフユ", 3, "こんなに迂遠で非効率的な計画を\n立てる敵になんて負けないわ！\n効率を極めた私たちの一撃を\n叩きつけてやりましょう！", "vo_empress_104801_004", 172, 1, 104801, 5, "", 104802, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104901_001", "シズル", 1, "安心していいよ、弟くん♪\n弟くんには指一本触れさせない！\n絶対に弟くんを守るから…だって\nそれがお姉ちゃんの役目だもんね！", "vo_empress_104901_001", 173, 1, 0, 5, "", 104902, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104901_002", "シズル", 1, "準備はできてる、弟くん？\n不安なら手をつないであげよっか？\n大丈夫、お姉ちゃんと弟くんなら\n悪いやつらを全部倒せるはず♪", "vo_empress_104901_002", 174, 1, 0, 5, "", 104902, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104901_003", "シズル", 2, "幻境竜后…手強そうだね…\nでも諦めないよ、絶対に！\n弟くんとお姉ちゃんの大切な世界\nきっと守り抜いてみせるんだから！", "vo_empress_104901_003", 175, 1, 0, 5, "", 104903, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_104901_004", "シズル", 3, "お姉ちゃんと弟くんの力を合わせて\n二人の未来を、みんなの未来を\n一緒に守ろっ！　あ、終わったら\nたくさん甘えさせてあげるからね♪", "vo_empress_104901_004", 176, 1, 104901, 5, "", 104902, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105001_001", "ミサキ", 1, "アブナイキレイなお姉さんはね\n『ふれーばー』だから許されるの！\nこんなメチャクチャにするなんて…\n本物の大人のレディが勝負よ勝負！", "vo_empress_105001_001", 177, 1, 0, 5, "", 105001, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105001_002", "ミサキ", 1, "アタシは全世界代表の\n大人のレディなんだから！\nアンタ！\nしっかりエスコートしてよね！", "vo_empress_105001_002", 178, 1, 0, 5, "", 105001, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105001_003", "ミサキ", 2, "コ、コイツが幻境竜后…っ\n…正直怖いけど…絶対に逃げないわ\n大人のレディのプライドにかけて\n戦い抜いてやるんだから…！", "vo_empress_105001_003", 179, 1, 0, 5, "", 105003, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105001_004", "ミサキ", 3, "終わったらデートよ！　だって…\n約束があった方がやる気出るもん♪\nよーし！　大人のレディとして\n最後はエレガントに決めるわよ！", "vo_empress_105001_004", 180, 1, 105001, 5, "", 105002, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105101_001", "ミツキ", 1, "なんて重圧かしら…でも、あいにく\n私も伊達に修羅場をくぐってないの\nさあ、かかってきなさい！\n裏の人生経験、見せてあげるわ…♪", "vo_empress_105101_001", 181, 1, 0, 5, "", 105101, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105101_002", "ミツキ", 1, "私は闇医者である前に科学者なの\nあなたたち、実験に協力してくれる\nわよね？　隻眼の悪魔の名は\n伊達じゃないのよ？　覚悟しなさい", "vo_empress_105101_002", 182, 1, 0, 5, "", 105101, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105101_003", "ミツキ", 2, "到底不可能に思える挑戦こそ\n科学者の腕の見せどころなのよ\n青い薔薇のごとく、人の信念が\n起こす奇跡を見せてあげるわ…！", "vo_empress_105101_003", 183, 1, 0, 5, "", 105101, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105101_004", "ミツキ", 3, "迷いのない言葉をもらったんだもの\n私だってもう、覚悟を決めたわ\nこの先の未来を君と生きていく…\nそのために全力をぶつけるだけよ！", "vo_empress_105101_004", 184, 1, 105101, 5, "", 105101, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105201_001", "リマ", 1, "私のお友達をいじめるなら\n相手になるわ！\nたとえ魔物に間違えられても\n絶対にここを引かないから！", "vo_empress_105201_001", 185, 1, 0, 5, "", 105201, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (10000, "vo_empress_105201_002", "リマ", 4002, "ね、ねぇ…\nちょっと聞きたいんだけど\n毛皮もないのにあの姿なのよね？\n風邪引いたりしないのかしら？", "vo_empress_105201_002", 186, 1, 0, 3, 1, 105201, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105201_003", "リマ", 2, "ひづめは割れちゃいそうだし…\n毛並みだってボロボロだし…\nでも後ろには彼がいるんだもの\n恋する乙女の負けられない戦いよ！", "vo_empress_105201_003", 187, 1, 0, 5, "", 105201, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105201_004", "リマ", 3, "私はもう恋する女の子じゃないわ…\n王子様の愛を受け取ったお姫様よ！\n彼が私を守ってくれるように\n私が彼を守ってみせるわ！", "vo_empress_105201_004", 188, 1, 105201, 5, "", 105202, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105301_001", "モニカ", 1, "どれほど強大な敵であろうと、\n我々【ヴァイスフリューゲル\nランドソル支部】がいれば安心…\nこら！　皆纏まって行動しろー！", "vo_empress_105301_001", 189, 1, 0, 5, "", 105303, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105301_002", "モニカ", 1, "敵戦力は強大無比…だが、\n私たちなら必ず倒せるはずだ！\n白き翼の名のもとに、今こそ\n正義の鉄槌を下してやる！", "vo_empress_105301_002", 190, 1, 0, 5, "", 105301, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105301_003", "モニカ", 2, "これが幻境竜后の底力か…\n名にし負う圧倒的な強さだな…\nだが！　長期戦になろうとも必ずや\n私たちが勝利の旗を掲げるのだ！", "vo_empress_105301_003", 191, 1, 0, 5, "", 105301, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105301_004", "モニカ", 3, "貴公と一緒ならば\nなんだってできるとも\nさあ、最後の一撃を加えてやろう！", "vo_empress_105301_004", 192, 1, 105301, 5, "", 105302, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105401_001", "ツムギ", 1, "強そうな相手ばかりですけど\nだからなんだっていうんですか！\nほら、騎士さんも気合い入れて！\n一緒に戦いますよ！", "vo_empress_105401_001", 193, 1, 0, 5, "", 105401, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (10000, "vo_empress_105401_002", "ツムギ", 4002, "なんか敵に下着姿…っていうか\nほぼ裸みたいな人いません？\n…え？　あれ趣味なんですか？\nあの人の？　…正気ですか？", "vo_empress_105401_002", 194, 1, 0, 3, 1, 105403, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105401_003", "ツムギ", 2, "世界を作り変えようなんて\n幻境竜后、絶対許せません…！\nあとその服！　そんなに破いて！\nデザイナーが泣いてますよ！", "vo_empress_105401_003", 195, 1, 0, 5, "", 105403, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105401_004", "ツムギ", 3, "私と騎士さんの糸は\n絶対に切れません！\nだから…今ここで\nすべてを終わらせましょう！", "vo_empress_105401_004", 196, 1, 105401, 5, "", 105401, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105501_001", "アユミ", 1, "つ、強そうな人たちばっかり…\n逃げたいくらいだけど、\nそれはダメ。先輩をケガさせない\nためにも、私も頑張らなくちゃ！", "vo_empress_105501_001", 197, 1, 0, 5, "", 105503, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105501_002", "アユミ", 1, "私なんかが大それたことを言うのは\n笑われるかも…でも…！\n先輩を守るために、\n世界を守ってみせます…！", "vo_empress_105501_002", 198, 1, 0, 5, "", 105501, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105501_003", "アユミ", 2, "な、なんて大きさ、存在感…！\nまるで私とは真逆の人…\nこうして立ってるだけで、\n私、消えちゃいそうです～っ…！", "vo_empress_105501_003", 199, 1, 0, 5, "", 105503, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105501_004", "アユミ", 3, "先輩がそばにいてくれる…\nそれだけで勇気が湧いてきて\n前へ進む力がもらえるんです\n行きましょう、先輩！", "vo_empress_105501_004", 200, 1, 105501, 5, "", 105502, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105601_001", "ルカ", 1, "雁首並べてよくもまあ…\nこりゃ長丁場になりそうだ\n釣りと同じくじっくり腰を据えて\n勝負しようじゃないか", "vo_empress_105601_001", 201, 1, 0, 5, "", 105601, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105601_002", "ルカ", 1, "世界の危機とあっちゃあ\nアタシたち黄昏時の住人でも\n黙っちゃいられないね！\nひとっ働きさせてもらおうかい！", "vo_empress_105601_002", 202, 1, 0, 5, "", 105601, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105601_003", "ルカ", 2, "へぇ、これが幻境竜后かい…\nたいそうな強さだけど、アタシも\nここで退くわけにはいかないんだ\n心に差した刃に懸けて、いくよ！", "vo_empress_105601_003", 203, 1, 0, 5, "", 105603, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105601_004", "ルカ", 3, "刀も恋も揃ったアタシは天下無双！\nお前さんが側にいてくれれば、\nどんな巨悪にだって勝てるよ！", "vo_empress_105601_004", 204, 1, 105601, 5, "", 105602, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105801_001", "ペコリーヌ", 1, "また一緒に、みんなで\nおいしいごはんを食べるために！\nわたしたちは、絶対に負けません！", "vo_empress_105801_001", 205, 1, 0, 5, "", 105803, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (10000, "vo_empress_105801_002", "ペコリーヌ", 4003, "フレイヤさんだけじゃなく、\n覇瞳皇帝やミロクまで！\n長丁場になりそうです…\n栄養補給はしっかりしましょうね！", "vo_empress_105801_002", 206, 1, 0, 3, 1, 105801, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105801_003", "ペコリーヌ", 2, "これが、幻境竜后の力…\nやばいですね。正直、どうやって\n止めればいいのか分かりません\nでもここで引き下がるわけには…っ", "vo_empress_105801_003", 207, 1, 0, 5, "", 105803, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105801_004", "ペコリーヌ", 3, "あなたの愛情でお腹いっぱいの\n無敵ペコリーヌ参上です☆\nわたしたちの明日を、この世界を\n全力全開で取り戻しましょう！", "vo_empress_105801_004", 208, 1, 105801, 5, "", 105802, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105901_001", "コッコロ", 1, "みなさまとのおいしいごはんのため\n負けるわけにはまいりません\n主さま、お背中はお任せください\nわたくしがお守りいたします！", "vo_empress_105901_001", 209, 1, 0, 5, "", 105903, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105901_002", "コッコロ", 1, "敵は強大…ですが、心強い仲間の\nみなさまが一緒でございます\n…全員主さまとお知り合いなのは\n未だに信じられませんが…", "vo_empress_105901_002", 210, 1, 0, 5, "", 105905, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105901_003", "コッコロ", 2, "まだこのような力が…！？\n主さま、ここはお下がりください\nたとえこの身に何があろうと、\nあなただけはお守りいたします…！", "vo_empress_105901_003", 211, 1, 0, 5, "", 105903, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_105901_004", "コッコロ", 3, "主さまとの絆がある限り\nわたくしは絶対に負けません！\nいついかなるときも、何があろうと\nわたくしが導いてみせます！", "vo_empress_105901_004", 212, 1, 105901, 5, "", 105902, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (10000, "vo_empress_106001_001", "キャル", 4005, "また陛下と戦うのね…大丈夫、一番\n大事なものが何なのかは分かってる\n…だから、あたしも負けないわ\n─陛下、よろしくお願いします！", "vo_empress_106001_001", 213, 1, 0, 3, 1, 106001, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_106001_002", "キャル", 1, "この世界を好き勝手しようだなんて\nそういう連中に人生振り回されるの\nこちとらもううんざりなのよ！\n全員ぶっ飛ばしてやるんだから！", "vo_empress_106001_002", 214, 1, 0, 5, "", 106003, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_106001_003", "キャル", 2, "なんなのよあの力、反則でしょ…\nだけどさ、どんなに怖くたって\nあたしはここから退かないわ\n他に行くとこも、ないんだからっ…", "vo_empress_106001_003", 215, 1, 0, 5, "", 106003, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_106001_004", "キャル", 3, "絆の力でパワーアップ、なんて\nガラじゃないと思ってたけど…\n今だけは調子に乗らせてもらうわ\nもう負ける気がしないってねっ！", "vo_empress_106001_004", 216, 1, 106001, 5, "", 106002, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_106101_001", "ノウェム", 1, "晶に直してもらって\n天楼覇断剣も新品同然だ！\n気合い入れていくぞオクトー！\nはーっはっはっはー！", "vo_empress_106101_001", 217, 1, 0, 5, "", 106102, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_106101_002", "ノウェム", 1, "真那、覚悟しとけよ！\nオマエが積み上げてきた悪事…\nこの大悪党がまとめて\nぶっ壊してやるからな！", "vo_empress_106101_002", 218, 1, 0, 5, "", 106101, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_106101_003", "ノウェム", 2, "今までの借り…ここでまとめて\n返してやるって、決めてたんだ\nオマエだけは絶対に、許さない\n…オマエが、どれだけ強くても…っ", "vo_empress_106101_003", 219, 1, 0, 5, "", 106103, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_106101_004", "ノウェム", 3, "大悪党のプリンセス？\nなんだかよくわからないけど──\nとにかく、あの化け物ぶった斬りに\n行くぞ！　ついてこい！", "vo_empress_106101_004", 220, 1, 106101, 5, "", 106102, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_106401_001", "シェフィ", 1, "絶対に負けられない戦いね\nおいしいごはんと、本当の\nハッピーエンドのために\n気を引き締めていきましょう", "vo_empress_106401_001", 221, 1, 0, 5, "", 106401, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (10000, "vo_empress_106401_002", "シェフィ", 4004, "ミロク…まだ生きていたのね…！\nあの男は私が相手するわ\n兄さんの分もまとめて、\n今ここで借りを返さないと！", "vo_empress_106401_002", 222, 1, 0, 3, 1, 106403, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_106401_003", "シェフィ", 2, "こんな力を隠してたなんて…！\n…まだよ。まだ諦めないわ\nどんな方法を使ってでも\nみんなだけは助けてみせる…！", "vo_empress_106401_003", 223, 1, 0, 5, "", 106401, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_106401_004", "シェフィ", 3, "不思議ね…あなたとの思い出で\n全身に力が満ちていくような気持ち\n…私たちが紡いできた絆を\n幻境竜后に見せてやりましょう", "vo_empress_106401_004", 224, 1, 106401, 5, "", 106402, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_106501_001", "カヤ", 1, "おまえら、ケンカ売りたいんだろ？\nこの世界そのものに！\nならこっち向けよ。喧嘩屋のオレが\nまとめて買ってやるぜ！", "vo_empress_106501_001", 225, 1, 0, 5, "", 106501, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_106501_002", "カヤ", 1, "オレがドラゴン族なのも、\nこんな力を持ってるのも…きっと\n今日、この時のためだったんだ\nそうだろ？", "vo_empress_106501_002", 226, 1, 0, 5, "", 106501, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_106501_003", "カヤ", 2, "ウソだろ…オレが竦んじまってる…\nアイツのあの赤い眼から、眼を\nそらすんじゃねぇ…！　ドラゴン族\nのケンカ最強は…オレ様だろッ…！", "vo_empress_106501_003", 227, 1, 0, 5, "", 106503, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_106501_004", "カヤ", 3, "自分の力に、ずっとビビッてた\nでも今は何よりこの力を頼もしく\n感じるぜ。テメェをぶっ倒し…\n明日を迎えるための力がなァ！", "vo_empress_106501_004", 228, 1, 106501, 5, "", 106501, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_106601_001", "イノリ", 1, "どきやがれです！　最強ギャングが\nおまえのシマ分捕りにきたですよ！\nこんだけ仲間がいりゃ楽勝ですね♪\n尻尾巻いて逃げ出しやがれです！！", "vo_empress_106601_001", 229, 1, 0, 5, "", 106603, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_106601_002", "イノリ", 1, "あっちもゾロゾロつれてきやがり\nましたね…へんっ、このあたしが\nビビビビるとでもおお思うですか\n…お、お兄さん、どどどこです？", "vo_empress_106601_002", 230, 1, 0, 5, "", 106601, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_106601_003", "イノリ", 2, "…！　あたしと同じドラゴン族？\nボスをプリンセスナイトに従えて\nたとか…へんっ、信じねーです！\nまあボスより性悪そ…ぴゃああっ", "vo_empress_106601_003", 231, 1, 0, 5, "", 106603, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_106601_004", "イノリ", 3, "ふっふっふ～ん！　熱い力が\nどんどん溢れてくるですよっ！\nさあ、懲らしめてやるですっ！\nおしりペンペンですよ！", "vo_empress_106601_004", 232, 1, 106601, 5, "", 106602, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_106701_001", "ホマレ", 1, "ふふっ、強そうな子がいっぱいだね\nそれじゃあ、誰が一番か決めよっか\nヴィーちゃんのプリンセスナイトで\n歴代最強は誰なのかを、ね♪", "vo_empress_106701_001", 233, 1, 0, 5, "", 106701, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_106701_002", "ホマレ", 1, "ヴィーちゃんてば、そんな子たちと\n一緒にいるほうが楽しいんだ～？\nじゃ、私たちも見せつけないとだね\n遠慮なくやっちゃおう☆　あははっ", "vo_empress_106701_002", 234, 1, 0, 5, "", 106701, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_106701_003", "ホマレ", 2, "これが、ヴィーちゃんの本気…\nとってもとってもすごいなぁ\n怖がりだからこそ、そんなに\n強くなれちゃったのかな…", "vo_empress_106701_003", 235, 1, 0, 5, "", 106703, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_106701_004", "ホマレ", 3, "残念だけど、ヴィーちゃん…\nもうゲームオーバーみたいだよ\nあなたとのどんなゲームも私には…\n全部ドキドキして、楽しかったな", "vo_empress_106701_004", 236, 1, 106701, 5, "", 106702, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_106801_001", "ラビリスタ", 1, "毎度、予想を超える困難ばかり\n押し寄せてくるんだからさ～\nま、アタシと少年が居る以上、\n好きにはさせないよ、ってね！", "vo_empress_106801_001", 237, 1, 0, 5, "", 106802, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (10000, "vo_empress_106801_002", "ラビリスタ", 4005, "よりによって真那まで相手かぁ…\nこりゃ一筋縄じゃいかなそうだ\n誰に対応するかは任せるけど、\n真那を相手取るなら頼ってよ", "vo_empress_106801_002", 238, 1, 0, 3, 1, 106801, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_106801_003", "ラビリスタ", 2, "当然、奥の手も用意してくるよね\n次から次へと用意周到だこと…\nとはいえこっちも負けられない\nこの難局の突破口を探すとしよう！", "vo_empress_106801_003", 239, 1, 0, 5, "", 106801, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_106801_004", "ラビリスタ", 3, "七冠…しかも幻境竜后が相手なら\n手は抜けそうにもないね\nはは、でもアタシたちならきっと\n乗り越えられーる！　だよね少年♪", "vo_empress_106801_004", 240, 1, 106801, 5, "", 106802, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (10000, "vo_empress_107001_001", "ネネカ", 4005, "真那…ふふ、こんなところで相対\nすることになるとは。いつぞやの\n借り、返してあげますよ。用意は\nいいですね？　マサキも、貴方も", "vo_empress_107001_001", 241, 1, 0, 3, 1, 107001, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_107001_002", "ネネカ", 1, "数で私たちを圧倒しようなど…\n底の浅い戦略ですね。返り討ちに\nしてあげましょう…この世界を\nまだ失うわけにはいきませんから", "vo_empress_107001_002", 242, 1, 0, 5, "", 107001, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_107001_003", "ネネカ", 2, "この力…計算外ではありますが\nそれは予想外という意味では\nありません。ええ、楽しみましょう\n不可能を解く、方程式の探求を", "vo_empress_107001_003", 243, 1, 0, 5, "", 107001, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_107001_004", "ネネカ", 3, "特等席で観察させてもらいましょう\n貴方の『心』という変数が\n『レジェンドオブアストルム』に\nどのような影響を与えるのかを…", "vo_empress_107001_004", 244, 1, 107001, 5, "", 107002, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_107101_001", "クリスティーナ", 1, "クリスティーナさんのご登場だよ☆\nあっははは……☆　またとない宴だ\n心行くまで愉しもうじゃあないか\n血で血を洗うダンス…滾るな♪", "vo_empress_107101_001", 245, 1, 0, 5, "", 107101, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (10000, "vo_empress_107101_002", "クリスティーナ", 4005, "真那さまがお出ましか…ワタシは\n本当に運がいいと見える♪　本気で\n刃を交える機会が巡ってくるなど\n願ってもない幸運だよ☆", "vo_empress_107101_002", 246, 1, 0, 3, 1, 107101, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_107101_003", "クリスティーナ", 2, "…ここで退くなど興冷めだろう？\nたとえ足が竦んだとしても…退屈に\n食われるよりもよほどいい！\n最後まで愉しみつくしてやるさ…☆", "vo_empress_107101_003", 247, 1, 0, 5, "", 107103, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_107101_004", "クリスティーナ", 3, "誤算だったなあ、『幻境竜后』\n他の者ならいざ知らず…\nキサマを殺せる唯一の力\n手にしたのはこの『誓約女君』だ！", "vo_empress_107101_004", 248, 1, 107101, 5, "", 107102, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_110801_001", "クロエ", 1, "ざーす。世界を救う系の光バイトで\n来たんすけど…あ、説明とかは\n大丈夫っす。慣れてるんでノリで\n入れます─おのれ世界の敵め！", "vo_empress_110801_001", 249, 1, 0, 5, "", 110801, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (10000, "vo_empress_110801_002", "クロエ", 4005, "なっつ、狐のねえさんいるじゃん\nまだ現役で悪モンやってたんだ\nてか中ボスポジに降格してるくね？\n世界の敵界隈、意外とせちがれーな", "vo_empress_110801_002", 250, 1, 0, 3, 1, 110801, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_110801_003", "クロエ", 2, "なんかヤベーの出てきたな…\nこのカンジ、若干最悪っていうか\nぶっちゃけ流れ変わったくない？\nこっから捲るのは…結構ダルいわ", "vo_empress_110801_003", 251, 1, 0, 5, "", 110803, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_110801_004", "クロエ", 3, "ちょ、聞いて敵、ウケんだけど\nなんかうち主人公だったみたいだわ\n山場でヒロインに力託され系のやつ\nてわけで、勝ち確いただきでーす", "vo_empress_110801_004", 252, 1, 110801, 5, "", 110802, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_110901_001", "チエル", 1, "ちぇるーん☆　ボス敵のみんな～！\n初めまして＆お久しブリリアント！\n世界の美少女ちえるんでっす！\n今からぼっこぼこにしてあげるね！", "vo_empress_110901_001", 253, 1, 0, 5, "", 110901, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_110901_002", "チエル", 1, "クリスＰの敵はカルミナの敵！\nカルミナの敵はなかよし部の敵！\nツアー全通めざして戦います！\n現場の平和はチエルが守る！", "vo_empress_110901_002", 254, 1, 0, 5, "", 110901, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_110901_003", "チエル", 2, "あ、あのう…ヤバくないです？\n敵のねえさん、急に年末歌合戦の\nラスボス衣装みたくなりましたけど\nえ、どーしよ…揚げます白旗？", "vo_empress_110901_003", 255, 1, 0, 5, "", 110903, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_110901_004", "チエル", 3, "世界の敵さん、ごめんちゃい！\nなんか愛だか絆だかの超理論的な\nアレでチエル覚醒しちゃいました！\nちぇるっと終わらせてあげますね！", "vo_empress_110901_004", 256, 1, 110901, 5, "", 110902, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_111001_001", "ユニ", 1, "世界の危機だって？　何度目だね？\nざまあみろだよ、勝手に滅べば…\nなに、地球の危機？　この箱庭の\n話ではなく？　何ソレ一大事！", "vo_empress_111001_001", 257, 1, 0, 5, "", 111001, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_111001_002", "ユニ", 1, "お、おい…敵が多すぎないか…？\n端の方でわちゃわちゃしてるだけの\n数合わせ要員として来たのだが…\nどういう事だ、聞いてた話と違うぞ", "vo_empress_111001_002", 258, 1, 0, 5, "", 111001, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_111001_003", "ユニ", 2, "あばば…なんだ、あの奇怪な姿は…\nあれが理系をこじらせた者の末路か\n宇宙暗黒理系女…どうしてあんなに\nなるまで放っておいたんだ…", "vo_empress_111001_003", 259, 1, 0, 5, "", 111003, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_111001_004", "ユニ", 3, "はん、驕ったな理系の女王よ\n世界は君が思うほど四角くない\n高機能計算機の弾いた数字ごときで\nぼくと彼の行間までは測れまいよ！", "vo_empress_111001_004", 260, 1, 111001, 5, "", 111002, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_118001_001", "クレジッタ", 1, "ですからわたくしは商人で、\n戦いなどは不向き…などと\n言ってる場合ではありませんわね！\n参りますわよ、我が陛下のために！", "vo_empress_118001_001", 261, 1, 0, 5, "", 118001, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_118001_002", "クレジッタ", 1, "ああもうはあもう、あっちこっち\n滅茶苦茶にしてくださってからに！\n復興費用の賠償はどなたに\n請求すればよろしいのかしら！？", "vo_empress_118001_002", 262, 1, 0, 5, "", 118003, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_118001_003", "クレジッタ", 2, "でっか！？　でっっっっか！！！\n幻境竜后でしたかしら！？\nなんなんですのあの高層建築な方、\n建築基準法違反ですわよ～っ！？", "vo_empress_118001_003", 263, 1, 0, 5, "", 118003, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_118001_004", "クレジッタ", 3, "ホーッホッホッホ！　幻境竜后さん\n貴方にはいらっしゃるのかしら！\n利害でなくその理想のために\n命を賭ける、真実の忠臣が！", "vo_empress_118001_004", 264, 1, 118001, 5, "", 118002, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_118101_001", "ランファ", 1, "恐ろしくて強そうな音が…たくさん\nでも…きっと、大丈夫。あなたや、\nミソラちゃん…みんなが一緒で…\nあたたかい音も、たくさんだもの…", "vo_empress_118101_001", 265, 1, 0, 5, "", 118101, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_118101_002", "ランファ", 1, "緊張、してる…？　そ、それなら、\nわたしに、任せて…わたし、歌を、\n歌うわね…聴けばきっと、いつも\n通りの力を、出せると思うから…", "vo_empress_118101_002", 266, 1, 0, 5, "", 118101, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_118101_003", "ランファ", 2, "お、音と声が、すごい…\nなんて…なんて恐ろしいのかしら…\n…？　で、でも…この音。\n幻境竜后も、恐怖…している…？", "vo_empress_118101_003", 267, 1, 0, 5, "", 118103, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_118101_004", "ランファ", 3, "わたしの歌が、どれほど役立つかは\nわからない…そ、それでもっ、\nあなたの力になりたいの…だから\nわたし、精一杯、歌うわね…", "vo_empress_118101_004", 268, 1, 118101, 5, "", 118102, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (10000, "vo_empress_118201_001", "ミソラ", 4005, "わー、ミロクさんや覇瞳皇帝さんも\nいるじゃないですか★\nそれじゃあわたしのガトリングで\nご挨拶といきましょっか♪", "vo_empress_118201_001", 269, 1, 0, 3, 1, 118201, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_118201_002", "ミソラ", 1, "騎士さんと力を合わせればどんな\n敵もほにゃららら～★　って感じで\nなんとかなると思うんですよねー\nほら、主人公補正ってやつで♪", "vo_empress_118201_002", 270, 1, 0, 5, "", 118201, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_118201_003", "ミソラ", 2, "復讐って、イイコトですかね？\n悪いコトですかね？まぁとりあえず\nぶっ壊してから考えましょうか\nね、幻境竜后さん─", "vo_empress_118201_003", 271, 1, 0, 5, "", 118202, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_118201_004", "ミソラ", 3, "騎士さんに選んでもらっちゃいまし\nたし、いらない縁とはバイバイした\nいんですよねー♪　ってわけで、\nここで終わりにさせてもらいます★", "vo_empress_118201_004", 272, 1, 118201, 5, "", 118202, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_118501_001", "カリン", 1, "みなさんの力を信じて、\n私も全力でサポートします\n連携と創意工夫があれば、きっと\nこの難局も乗り越えられます！", "vo_empress_118501_001", 273, 1, 0, 5, "", 118501, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_118501_002", "カリン", 1, "過去最大級の強敵が現れました！\nギルド管理協会を代表して…\nあなたに討伐を依頼します！\n報酬はお望みのままに、ですよ♪", "vo_empress_118501_002", 274, 1, 0, 5, "", 118502, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_118501_003", "カリン", 2, "…っ。さすがの強敵ですね…\nだからこそ、焦りは禁物…です\nあらゆる事態を想定して、ギルドの\nみなさんを支援するのが私の仕事…", "vo_empress_118501_003", 275, 1, 0, 5, "", 118503, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_118501_004", "カリン", 3, "あなたと共に進めば\nどんな壁も越えられます\n私の、大切な人の無事を信じて…\n今こそ全力を尽くします！", "vo_empress_118501_004", 276, 1, 118501, 5, "", 118502, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_118601_001", "ネビア", 1, "あんな奴らを野放しにしてたら\nこの世界が滅茶苦茶にされちゃう！\nでもまぁこれはこれでチャンスよ♪\n最っ高の悪戯の標的にしてあげる！", "vo_empress_118601_001", 277, 1, 0, 5, "", 118601, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_118601_002", "ネビア", 1, "私はただのガイド妖精、みんなに\n比べれば大した力も持ってない…\nでも悪戯妖精なりの意地があんのよ\nあいつらに一泡吹かせてやるわ♪", "vo_empress_118601_002", 278, 1, 0, 5, "", 118601, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_118601_003", "ネビア", 2, "幻境竜后、なんて力の持ち主なの\n正直きっついわ…でもまだやれる\n私はデータよ、壊れたって\nあんたを守る壁くらいにはなれる…", "vo_empress_118601_003", 279, 1, 0, 5, "", 118603, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_118601_004", "ネビア", 3, "覚悟しなさいっ！\n出来損ないの悪戯妖精をなめたら\n痛い目に遭うって教えてあげる\nさぁ、最高のショーの始まりよ！", "vo_empress_118601_004", 280, 1, 118601, 5, "", 118602, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_122301_001", "ヴァンピィ", 1, "むー！　いたずらっこの暴れんぼ\nさんたちは、ヴァンピィちゃんが\nきつーくおしおきしちゃうよ！\n真祖のおつとめですから！", "vo_empress_122301_001", 281, 1, 0, 5, "", 122303, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_122301_002", "ヴァンピィ", 1, "けんぞくはヴァンピィちゃんの\n背中に隠れてなさいっ。え？\n背中を守りたい？　うん、それなら\nよろしい！　一緒だよ、けんぞく！", "vo_empress_122301_002", 282, 1, 0, 5, "", 122302, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_122301_003", "ヴァンピィ", 2, "幻境竜后？　ふーんだ！\nベスちゃんのほーが、ずーっと\n強くてカッコいいですし！\nいくよっ、けんぞくぅ！", "vo_empress_122301_003", 283, 1, 0, 5, "", 122303, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_122301_004", "ヴァンピィ", 3, "ここはみんなの『いばしょ』！\n壊しちゃうなんて、許さないもん\nヴァンピィちゃん、本気で怒ったよ\nやっちゃうよ、けんぞく！", "vo_empress_122301_004", 284, 1, 122301, 5, "", 122302, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_123001_001", "アメス", 1, "ほら、あんたは余計な心配しないの\nあいつらに好き勝手させないように\n全力でぶつかっていくだけよ\nあたしたちの未来のためにね♪", "vo_empress_123001_001", 285, 1, 0, 5, "", 123002, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_123001_002", "アメス", 1, "…あの連中も強くてやばいけど…\n一番やばいのは、こんなにたくさん\n女の子の知り合いがいる\nあんたかもしれないわね…", "vo_empress_123001_002", 286, 1, 0, 5, "", 123001, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_123001_003", "アメス", 2, "なんて相手なの…さすがに想定を\n超えてるわよ…こんなの卑怯よね\nだからってここで逃げやしないわよ\nせめて、あんたを守るくらいは…！", "vo_empress_123001_003", 287, 1, 0, 5, "", 123003, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_123001_004", "アメス", 3, "敵がどれだけ強くたって関係ないわ\nあんたの行く道はあたしが照らす\n迷ったらあたしを見なさい\nどこまでだって導いてあげる！", "vo_empress_123001_004", 288, 1, 123001, 5, "", 123002, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_123301_001", "ネア", 1, "『レギオンウォー』思い出すな～\nあん時は敵側だったけどー\n今回は騎士きゅんたちの隣で\nネアおねえちゃんもがんばるぞ～♡", "vo_empress_123301_001", 289, 1, 0, 5, "", 123301, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_123301_002", "ネア", 1, "だる～、激ヤバなテキばっかじゃん\n騎士きゅんパワー充電しねーと\nおねえちゃんもギリギリかもー\nとりま、ちゅっちゅ♡　してい？", "vo_empress_123301_002", 290, 1, 0, 5, "", 123301, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_123301_003", "ネア", 2, "激ヤバドラゴン、ガチしんどー…\nま、だからって負ける気ねーけど\nこーゆう時こそ、スライムの\n粘り強さの見せ所っしょ～　ね♪", "vo_empress_123301_003", 291, 1, 0, 5, "", 123303, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_123301_004", "ネア", 3, "ンフフフフ～♪　今のアタシ、\n騎士きゅんと一心同体ってやつ～？\nめちゃめちゃアガるわ～♪\n愛の力パねぇ～♡", "vo_empress_123301_004", 292, 1, 123301, 5, "", 123302, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_126401_001", "クローチェ", 1, "ビーッ！　ビーッ！\nあっちもこっちもそっちも\n強そうな人たちでいっぱいですっ！\nセンサーが壊れちゃいそう～っ！", "vo_empress_126401_001", 293, 1, 0, 5, "", 126401, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_126401_002", "クローチェ", 1, "世界が大変なことになってますっ！\nでもわたしたちは今までだって、\n大変な戦いを乗り越えてきましたっ\nきっと…ううん、絶対勝てますっ！", "vo_empress_126401_002", 294, 1, 0, 5, "", 126401, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_126401_003", "クローチェ", 2, "ビビービビビーッ！　…ひゃあっ！\nセンサーが壊れちゃいました…！\nしかも、照準が震えちゃって…\n…これが…この感情が、恐怖…？", "vo_empress_126401_003", 295, 1, 0, 5, "", 126403, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_126401_004", "クローチェ", 3, "今のわたしたちに、怖いものなんて\nありませんっ！　敵さんがどんなに\n強くても…わたしとナイトさんの\n特別なパワーは、もっと強いです！", "vo_empress_126401_004", 296, 1, 126401, 5, "", 126402, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_126501_001", "ライラエル", 1, "ジオ・テオゴニアの姫として\nこの星に生きる一個として\nこれ以上の蹂躙を許すわけには\nいきません。そうですね？　騎士", "vo_empress_126501_001", 297, 1, 0, 5, "", 126501, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (10000, "vo_empress_126501_002", "ライラエル", 4002, "穢らわしい、色狂いの山羊めが\n我が従僕を傀儡としてくれた借り、\n兆倍──否、京倍にして\n返してくれようぞ。崩雷夜天！", "vo_empress_126501_002", 298, 1, 0, 3, 1, 126506, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_126501_003", "ライラエル", 2, "幻境竜后。迷いなく、圧倒的な力で\nわたしたちの調和を滅しようとする\nそんな力を、認めたくはないのに…\nなんて、困難な戦いなのでしょう…", "vo_empress_126501_003", 299, 1, 0, 5, "", 126503, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_126501_004", "ライラエル", 3, "この星には、あなたがいる…\n悪辣な侵略者と戦う理由など、\nただそれだけで十分です\n守りましょう。わたしたちの世界を", "vo_empress_126501_004", 300, 1, 126501, 5, "", 126502, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (10000, "vo_empress_127701_001", "リンド", 4002, "あそこにヴルムを傷つけた人が…！\n…騎士さん、絶対勝ちましょうね\nあの人たちのやったこと、私\n絶対ぜったい許しませんから！", "vo_empress_127701_001", 301, 1, 0, 3, 1, 127701, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_127701_002", "リンド", 1, "騎士さんたちと出会えたこの世界を\n悪いことになんか使わせません\n作り物だなんて信じられませんけど\n失っちゃいけないものはわかります", "vo_empress_127701_002", 302, 1, 0, 5, "", 127701, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_127701_003", "リンド", 2, "まだこんな力が残ってるの…！？\n考えなきゃ、私にできること…\n何か…何かないの…！？\nまた私、何もできないの…？", "vo_empress_127701_003", 303, 1, 0, 5, "", 127703, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_127701_004", "リンド", 3, "あなたが側にいてくれるから、\n私もこうして戦えます\nチョロいって言われてもいいです\n私にとって、大切なひとですから", "vo_empress_127701_004", 304, 1, 127701, 5, "", 127702, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_127801_001", "ヴルム", 1, "…正直、サボりとかじゃなくて…\nぜんぜん身体はきついです。でも…\n姉貴やみんなと過ごすこの世界は\n誰にも壊させやしませんから…！", "vo_empress_127801_001", 305, 1, 0, 5, "", 127801, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (10000, "vo_empress_127801_002", "ヴルム", 4002, "騎士さん…アルシャトのこと\nあたしにも一発殴らせてください\nふざけた真似してくれたお礼…\n倍にして返してやりますよ", "vo_empress_127801_002", 306, 1, 0, 3, 1, 127801, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_127801_003", "ヴルム", 2, "冗談きついです、こんなの…\n勝てっこないじゃないですか\nあたしだってドラゴン族なのに\nこれほどまでに差があるだなんて…", "vo_empress_127801_003", 307, 1, 0, 5, "", 127803, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_127801_004", "ヴルム", 3, "もう後先考えずにいきますよ\n面倒見てくれる人がここにいるので\nあたしと騎士さんが揃えば\n無敵だってとこ見せてやります", "vo_empress_127801_004", 308, 1, 127801, 5, "", 127802, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (10000, "vo_empress_129001_001", "エリス", 4005, "覇瞳皇帝…わたしの邪魔をするなら\nかつてのように、消去するだけ\nミロクも…わたしを草野優衣の\n複製と呼んだこと、後悔させてやる", "vo_empress_129001_001", 309, 1, 0, 3, 1, 129001, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_129001_002", "エリス", 1, "管理者の座は失っても\nわたしの意志は揺らがない…\n騎士クンの物語を紡ぐために…\nそれが、わたしの全てだから", "vo_empress_129001_002", 310, 1, 0, 5, "", 129001, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_129001_003", "エリス", 2, "これが七冠、幻境竜后の全力…\n管理者だったかつてのわたしを、\n超えるほどの脅威…でも、\n騎士クンだけは、守ってみせる…", "vo_empress_129001_003", 311, 1, 0, 5, "", 129003, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_129001_004", "エリス", 3, "孤独も絶望も越えてきた\nもうどんな闇にも迷わない\n騎士クンが隣にいる限り\nわたしは、負けない", "vo_empress_129001_004", 312, 1, 129001, 5, "", 129002, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_129601_001", "アネモネ", 1, "リアを──媛を、傷つけたひとたち\n笑ってられるのも今だけです──\nアルラウネの棘の鋭さ、\n教えてあげますから──", "vo_empress_129601_001", 313, 1, 0, 5, "", 129601, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_129601_002", "アネモネ", 1, "騎士のひと──背中は、任せます\n貴方のこと、\n媛と同じくらい、信じてるので──\n自分でも、びっくりですけど", "vo_empress_129601_002", 314, 1, 0, 5, "", 129601, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_129601_003", "アネモネ", 2, "私、ずっと抗ってきたんです\nそのために、強くなったはず──\nだから──諦めたく、ないです…", "vo_empress_129601_003", 315, 1, 0, 5, "", 129603, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_129601_004", "アネモネ", 3, "体が熱くて、思考がまとまらなくて\nなのに負ける気がしない──なんて\nよくわからないです。どうしてか、\n後で教えてください──騎士のひと", "vo_empress_129601_004", 316, 1, 129601, 5, "", 129601, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_129701_001", "ネフィ＝ネラ", 1, "難敵強敵揃い踏みなれど\nわっちらが退く理はありんせん\n騎士殿や、手を携えて此度の争乱\n鎮めて見せましょう也", "vo_empress_129701_001", 317, 1, 0, 5, "", 129701, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_129701_002", "ネフィ＝ネラ", 1, "今のわっちが萎弱であろうとて\n貴様等如き梟悪に斃される訳には\nゆかぬ也。再び足甲を舐めさせ\n地に臥すまで仕置きを致しんしょう", "vo_empress_129701_002", 318, 1, 0, 5, "", 129701, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_129701_003", "ネフィ＝ネラ", 2, "我が矜持『不退転』─如何なる敵で\nあろうとも揺らぐ仕儀はなし。斯様\nな邪竜程度、退けむと思い侍りしが\n─難儀な由、残念至極─…", "vo_empress_129701_003", 319, 1, 0, 5, "", 129703, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_129701_004", "ネフィ＝ネラ", 3, "参りまする也、騎士殿や\n懼るること等何一つ御座りんせん\n唯わっちらの勇儀を以て、此の星の\n明日を再び…掌中に致しんしょう", "vo_empress_129701_004", 320, 1, 129701, 5, "", 129702, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (10000, "vo_empress_130001_001", "ヤマト", 4003, "─おや、フレイヤじゃないか\nずいぶん様変わりしたようだが\n今の方がアタシとしちゃ好みだね\nお礼参りのしがいもあるってもんさ", "vo_empress_130001_001", 321, 1, 0, 3, 1, 130001, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_130001_002", "ヤマト", 1, "…フゥン？　あっちもこっちも\n『王家の装備』を持ってるらしいね\n宝の山ってのはこのことかい\nまとめて搔っ攫ってやろうかね…！", "vo_empress_130001_002", 322, 1, 0, 5, "", 130001, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_130001_003", "ヤマト", 2, "ちっ…、幻境竜后つったかい\n世界を奪おうってのも冗談じゃ\nなさそうだ。…ワカナ、フブキ…\nお前たちだけでも、逃げな…", "vo_empress_130001_003", 323, 1, 0, 5, "", 130003, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_130001_004", "ヤマト", 3, "アタシらの住み家を奪おうだぁ？\nハッ、笑わせてくれるね\n盗賊は盗むモンであって、\n盗まれるモンじゃあないンだよ！", "vo_empress_130001_004", 324, 1, 130001, 5, "", 130002, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_130101_001", "ワカナ", 1, "つ、強そうな人たちがたくさん…\nなのに姉さんもフブキちゃんも\nやる気満々だし…\nわたし、どうすればいいのぉ～っ", "vo_empress_130101_001", 325, 1, 0, 5, "", 130101, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_130101_002", "ワカナ", 1, "きっと、長期戦になりますよね…\nあ、あの…ご飯、食べませんか？\nお腹が空くといけないと思って、\n作ってきたので…よろしければっ", "vo_empress_130101_002", 326, 1, 0, 5, "", 130101, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_130101_003", "ワカナ", 2, "む…むりっ！　無理ですよ～っ！\nあんなおっきいドラゴンなんて、\n勝てるわけないじゃないですかっ\nに、逃げちゃいましょ、ねっ…！？", "vo_empress_130101_003", 327, 1, 0, 5, "", 130103, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_130101_004", "ワカナ", 3, "と、盗られるぐらいなら盗るのが\n【バンディ・シスターズ】流ですっ\n騎士さん、わたしたちの未来を\n掴み取りにいきましょう…っ！", "vo_empress_130101_004", 328, 1, 130101, 5, "", 130102, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_130201_001", "フブキ", 1, "だる～、ささっと片付けてきてよ～\nムリ？　知ってる～だってザコザコ\nお兄さんだもんね♪　しょーがない\n助けてあげよっかな～？きゃはは♡", "vo_empress_130201_001", 329, 1, 0, 5, "", 130201, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_130201_002", "フブキ", 1, "あの陰気ダサダサメガネさー、\n仲間集めてチョーシ乗ってねー？\nザコは何匹集まったってザコだって\nフブキちゃんが教えてあげまーす♪", "vo_empress_130201_002", 330, 1, 0, 5, "", 130201, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_130201_003", "フブキ", 2, "ふぇぇ…まじムリ、アイツムリ～！\n全然ラスボスってカンジじゃん！？\nぼくお家かえるぅ～っ！\nお兄さんも一緒にかえろっ、ねっ？", "vo_empress_130201_003", 331, 1, 0, 5, "", 130203, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_130201_004", "フブキ", 3, "お兄さん、やる気漲っちゃってる？\nだよねー、世界が滅んじゃったら\nぼくとも永遠のお別れなんだし？\n必死になるのもトーゼンっしょ～♡", "vo_empress_130201_004", 332, 1, 130201, 5, "", 130202, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_130901_001", "クルル", 1, "はわっ！？　すっごくすっごく\n悪そうな人達いっぱいですますぅ！\nかばばん君、警備員モードです！\nぴっぴーーーー！", "vo_empress_130901_001", 333, 1, 0, 5, "", 130901, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_130901_002", "クルル", 1, "この戦いが終わったら、みなさんと\nパークで凱旋パレードですぅ♪\n…ふぇっ？\n気が早いですますか？", "vo_empress_130901_002", 334, 1, 0, 5, "", 130901, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_130901_003", "クルル", 2, "はわわっ！　幻境竜后さん、\n強そうすぎですっ…でもっ！\nやっと再建したパークも世界も\nぜったい壊させないですよ～っ！", "vo_empress_130901_003", 335, 1, 0, 5, "", 130903, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_130901_004", "クルル", 3, "ヒーローさんのこと、\nクルルの全部でお助けしますです！\nジオ・テオゴニアでも、どんな世界\nでも…ずっと、ず～っとですっ！", "vo_empress_130901_004", 336, 1, 130901, 5, "", 130902, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_132301_001", "ルイズマリー", 1, "なっなんなのよこいつらっ！\nダーリンとの恋路を邪魔する気…？\nそんなことさせないわ…だって、\n二人の恋はエターナルですからっ！", "vo_empress_132301_001", 337, 1, 0, 5, "", 132301, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_132301_002", "ルイズマリー", 1, "愛情×愛情＝無限大…\n遂に錬金術の神髄に辿り着いたわ…\nさあ…お見舞いしてやりましょう！\n私とダーリンの究極錬成をっ！", "vo_empress_132301_002", 338, 1, 0, 5, "", 132301, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_132301_003", "ルイズマリー", 2, "あ、あなたがどんなに強くても、\n私は逃げないわ！　ダーリンに\nちょっかいかける奴は絶対に\n許さないって決めてるから…っ！！", "vo_empress_132301_003", 339, 1, 0, 5, "", 132303, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_132301_004", "ルイズマリー", 3, "悪いけど速攻で終わらせちゃうわ！\n早く帰ってダーリンと心行くまで\n破廉恥な乳繰り合い…じゃなくて！\n愛を確かめ合うんだからっ！", "vo_empress_132301_004", 340, 1, 132301, 5, "", 132302, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_132401_001", "イロハ", 1, "わわっ、敵がいっぱい！\nこれがクワガタだったら最高…よし\n新種のクワガタって事にしちゃお！\nあははっ！　待て待て～っ！！", "vo_empress_132401_001", 341, 1, 0, 5, "", 132401, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_132401_002", "イロハ", 1, "あはは、まだまだ出てくるね～！\nなら新しい技いっぱい\n試しちゃおっか…さあ、いくよ！\n──イスルギ流奥義っ！！", "vo_empress_132401_002", 342, 1, 0, 5, "", 132401, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_132401_003", "イロハ", 2, "あのおねーさんもなかなか良いツノ\n持ってるねえ♪　イロハが勝ったら\nルイちゃんと二人でクワガタ相撲\nごっこやってもらおっと！", "vo_empress_132401_003", 343, 1, 0, 5, "", 132401, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_132401_004", "イロハ", 3, "おねーさんがどんなに強くたって\nイロハは絶対に負けない！\nおじちゃんが見ててくれてる時の\nイロハは、サイキョーなんだから！", "vo_empress_132401_004", 344, 1, 132401, 5, "", 132402, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_132501_001", "ソノ", 1, "いや無理無理、戦いとか苦手過ぎる\n…でも君となら、奇跡起こせるかも\n…うわやば、今の忘れて\n若者みたいなこと言っちゃったよ…", "vo_empress_132501_001", 345, 1, 0, 5, "", 132501, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_132501_002", "ソノ", 1, "敵、まだいっぱいいるじゃん…\nはあ…残業したくないけど頑張るか\n全部終わったら君からのマッサージ\n期待しとくから、ね", "vo_empress_132501_002", 346, 1, 0, 5, "", 132501, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_132501_003", "ソノ", 2, "はあ…はあ…幻境竜后だっけ？\nルイちゃんの錬金術より\n出鱈目な強さだね…！\nでもまだまだ諦めない…いくよ！", "vo_empress_132501_003", 347, 1, 0, 5, "", 132503, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_132501_004", "ソノ", 3, "こんなに強い敵が相手でも\n諦めなきゃ勝てるんだって\n教えてくれたのは君だよ\nふふ…ありがとね、若者♪", "vo_empress_132501_004", 348, 1, 132501, 5, "", 132502, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_133001_001", "グレイス", 1, "うーわ。あっちもこっちも\nボス級だらけじゃないですか\nま、ヴァイオレット姫には\n指一本触れさせませんけどね", "vo_empress_133001_001", 349, 1, 0, 5, "", 133001, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (10000, "vo_empress_133001_002", "グレイス", 4001, "リーザ…今度こそ、決着の時ね\nいくら頭数を揃えても私は…いえ\n私と騎士氏は絶対に負けないわ\nこの槍で、冥界に送り返してあげる", "vo_empress_133001_002", 350, 1, 0, 3, 1, 133003, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_133001_003", "グレイス", 2, "ぐっ…圧倒的ですね『幻境竜后』\nですが…決してあきらめません\n私には、生きていてほしい人が\nたくさんいますので…！", "vo_empress_133001_003", 351, 1, 0, 5, "", 133003, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_133001_004", "グレイス", 3, "とてつもない強敵を前にしてるのに\nまるで恐怖心を感じません…\n…恋とは、心霊現象よりも\n不思議なものらしいですよ", "vo_empress_133001_004", 352, 1, 133001, 5, "", 133002, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_133101_001", "ヴァイオレット", 1, "恐るべき方々ばかりです…\nですがわたくしは絶対に退きません\nジオ・ニヴルヘルの姫として\nこの世界を守ると決めたのです！", "vo_empress_133101_001", 353, 1, 0, 5, "", 133101, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (10000, "vo_empress_133101_002", "ヴァイオレット", 4001, "リーザ…どうしてもわたくしたちの\n前に立ちはだかるというのですね\nならばわたくしも覚悟を決めました\nこの手であなたを、倒します…！", "vo_empress_133101_002", 354, 1, 0, 3, 1, 133101, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_133101_003", "ヴァイオレット", 2, "これが、彼女の本気の力…！\n異質で…故に、とても寂しい…\n本当の意味で彼女に届く声が、\nこの世界に存在するのでしょうか…", "vo_empress_133101_003", 355, 1, 0, 5, "", 133103, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_133101_004", "ヴァイオレット", 3, "あなたとの「繋がり」がある限り\n死が牙を剥くことはありません\n手を取り合い、共に参りましょう\nわたくしたちの未来のために！", "vo_empress_133101_004", 356, 1, 133101, 5, "", 133102, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_133601_001", "メドゥーサ", 1, "フンっ、次から次へと…！　なら\n思う存分、大暴れしてやるから♪\nやっちゃうわよ、メドゥシアナ！\nアンタも！！", "vo_empress_133601_001", 357, 1, 0, 5, "", 133601, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_133601_002", "メドゥーサ", 1, "どこの誰だか知らないけれど、\nアタシの魔眼でまとめて石に…って\nきゃああああ！　こんなバケモン級\nなら先に教えときなさいよ～っ！", "vo_empress_133601_002", 358, 1, 0, 5, "", 133601, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_133601_003", "メドゥーサ", 2, "な…なんなの、アイツの『眼』…\nでもねっ、アタシはメドゥーサ\nゴルゴーンの、お姉ちゃんの妹よ！\n睨みあいで負けるわけがないわ！", "vo_empress_133601_003", 359, 1, 0, 5, "", 133603, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_133601_004", "メドゥーサ", 3, "知ってる？　蛇って執念深いのよ\nこの『眼』で見つけてやったわ\n幻境竜后、アンタが一番恐れること\nアタシとこいつが手をつなぐこと！", "vo_empress_133601_004", 360, 1, 133601, 5, "", 133602, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_134701_001", "ホウオウ", 1, "この大地と大空を守るため、\n人の子らだけに任せてはおけません\n鳳凰のはばたきで、その野望ごと\n跡形もなく吹き飛ばしましょう！", "vo_empress_134701_001", 361, 1, 0, 5, "", 134701, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_134701_002", "ホウオウ", 1, "さあ皆さん、ここが正念場です！\n私がいれば楽勝圧勝間違いなし！\n…えっ？　私が先頭？　えーと…\nあっちょっと待って押さないで！", "vo_empress_134701_002", 362, 1, 0, 5, "", 134701, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_134701_003", "ホウオウ", 2, "羽が散って、ちっ、力が…\n幻境竜后、やるではないですか…\nしかし、私も不死鳥と呼ばれた身…\nただでやられは…ぴ、ぴよぉぉ～…", "vo_empress_134701_003", 363, 1, 0, 5, "", 134703, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_134701_004", "ホウオウ", 3, "幻境竜后、でしたか？\nあなたも運のない方ですね\n今の私は輪廻史上最強の鳳凰\nその鱗一つ残さず焼き尽くします！", "vo_empress_134701_004", 364, 1, 134701, 5, "", 134702, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_134901_001", "カノン", 1, "ヲ～ッホッホ！　どいつもこいつも\n大層なおツラ構えしてますけどぉ？\nあたくし様の敵じゃありませんわ！\nほら馬ボーン！　お強化なさいな！", "vo_empress_134901_001", 365, 1, 0, 5, "", 134901, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_134901_002", "カノン", 1, "いってぇ～ですわ！　あたくし様の\nお美しいお肌を傷つけましたわね！\nまとめてお成敗して差し上げますわ\nついてらっしゃいな！　馬ボーン！", "vo_empress_134901_002", 366, 1, 0, 5, "", 134901, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_134901_003", "カノン", 2, "なんてタマですの…アースハイドラ\nよりデカいなんて聞いてませんわ！\nでも…ここでお尻尾巻いて逃げる\nなら、死んだ方がマシですわ…！", "vo_empress_134901_003", 367, 1, 0, 5, "", 134903, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_134901_004", "カノン", 3, "幻境竜后とやら、お覚悟なさいな\nあたくしと馬ボーンの前に立つなど\n100億万年お早いですわ！\n華麗にお成敗して差し上げますわ♪", "vo_empress_134901_004", 368, 1, 134901, 5, "", 134902, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_135501_001", "アイラ", 1, "来たね、お姉さんの出番ってやつ♪\nキミと一緒に戦えるなんて、あたし\nテンション最高潮だよ！　あははっ\nさ、思いっきり暴れちゃおっか！", "vo_empress_135501_001", 369, 1, 0, 5, "", 135501, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (10000, "vo_empress_135501_002", "アイラ", 4005, "あれが…覇瞳皇帝のオリジナルだね\nま、関係ないや。本物でも偽物でも\n今度こそ決着つけてあげるから！\nお姉さんの拳…燃え盛ってるよー！", "vo_empress_135501_002", 370, 1, 0, 3, 1, 135501, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_135501_003", "アイラ", 2, "幻境竜后…とんでもない相手だね\nあたしの拳だって届かないかも…\nそれでも、燃え尽きるまで戦うよ\nキミが信じてくれてる限り、ね！", "vo_empress_135501_003", 371, 1, 0, 5, "", 135503, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_135501_004", "アイラ", 3, "キミがいれば怖いものなし！\nお姉さん今、燃えに燃えてるよっ\n太陽より熱く燃える拳で…\n全部まとめてぶっ飛ばす！", "vo_empress_135501_004", 372, 1, 135501, 5, "", 135502, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_135601_001", "シナツ", 1, "どれほどの逆風の中にいても、\n諦めてはならない…そうだろう？\nかつて私が、他でもないキミたちに\nそう教えてもらったんだ…", "vo_empress_135601_001", 373, 1, 0, 5, "", 135601, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_135601_002", "シナツ", 1, "私はこの世界の人々と出会い、\n失ったはずの希望を見つけられた\n今度は私が、皆に希望を届ける番だ\nこの刃、存分に振るわせてくれ", "vo_empress_135601_002", 374, 1, 0, 5, "", 135601, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_135601_003", "シナツ", 2, "幻境竜后…私たちの世界を創造し、\nそして滅ぼそうとした張本人か…！\nその力がどんなに強大だとしても…\n私は…絶対に逃げたりなどしない！", "vo_empress_135601_003", 375, 1, 0, 5, "", 135603, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_135601_004", "シナツ", 3, "私の刃に、もはや一片の曇りもない\n皆と生きる未来を守り抜くために\n戦いつづける…ただそれだけだ\n─道を阻む者は全て斬り伏せる！", "vo_empress_135601_004", 376, 1, 135601, 5, "", 135602, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (10000, "vo_empress_135801_001", "ユキノ", 4001, "リ、リ、リーザちゃ…！\nリーザちゃはあてのこと、ヘタレの\nホジナシって思ってっかもだけど…\n前より成長したとこ、見せっから！", "vo_empress_135801_001", 377, 1, 0, 3, 1, 135801, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_135801_002", "ユキノ", 1, "田舎者で世間知らずなあてだけど…\n騎士さと一緒にいろんなとこ行って\n大切な思い出、いっぱいできたよ…\nだから守りてぇんだ、この世界…！", "vo_empress_135801_002", 378, 1, 0, 5, "", 135801, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_135801_003", "ユキノ", 2, "あ、あても、ちったぁでけぇけど…\n幻境竜后、で、でっかすぎ…！\nそ、それに竜まで…！　炎浴びたら\nあて、溶けちまうよぅ…！", "vo_empress_135801_003", 379, 1, 0, 5, "", 135803, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_135801_004", "ユキノ", 3, "「あてなんか」なんて、考えね…\n騎士さが信じてくれるなら、\nあてだって自分のこと、信じるよ\nあてと騎士さなら大丈夫、って…！", "vo_empress_135801_004", 380, 1, 135801, 5, "", 135802, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (10000, "vo_empress_135901_001", "サツキ", 4001, "リザ公…手前ェどの面下げて\n俺の前に出てきやがった\nまァいいさ、何聞いても今更だ\nここで落とし前つけてもらうぜ", "vo_empress_135901_001", 381, 1, 0, 3, 1, 135903, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_135901_002", "サツキ", 1, "いつ死んでもいいなんて\nもう思っちゃいねぇさ\nこの悪玉どもより、図太くしぶとく\n生き抜いてやろうじゃねぇか", "vo_empress_135901_002", 382, 1, 0, 5, "", 135901, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_135901_003", "サツキ", 2, "あれが幻境竜后か…\nハンパじゃねェや\nしゃあねぇ、こうなりゃ一丁\n死に花咲かすとするか", "vo_empress_135901_003", 383, 1, 0, 5, "", 135901, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_135901_004", "サツキ", 3, "世界だの未来だの現実だの…\n重いったらありゃしねぇぜ\n潰れるなよ、騎士公\n俺も一緒に担いでやっからさ", "vo_empress_135901_004", 384, 1, 135901, 5, "", 135902, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_136001_001", "アラクネ", 1, "騎士さま、どうかご安心を…\nどれだけ厳しい運命が待って\nいたとしても…あなたのことは、\nわたしの糸が必ずお守りします", "vo_empress_136001_001", 385, 1, 0, 5, "", 136001, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (10000, "vo_empress_136001_002", "アラクネ", 4003, "…？　あの金髪の女性、なんだか\n見覚えあるような気が…いえ\n騎士さまの敵は、わたしの敵です\nそれだけです…", "vo_empress_136001_002", 386, 1, 0, 3, 1, 136001, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_136001_003", "アラクネ", 2, "あれが幻境竜后さま…\nなんという恐るべき力\n…騎士さま、わたしの後ろに\n一度くらいは、庇えるはずです…", "vo_empress_136001_003", 387, 1, 0, 5, "", 136003, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_136001_004", "アラクネ", 3, "騎士さまという光が、わたしに力を\n与えてくれるのです。ともに未来を\n歩むためにも…この戦いに\n必ず勝ちましょう、騎士さま", "vo_empress_136001_004", 388, 1, 136001, 5, "", 136002, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_136201_001", "ナーナ", 1, "強そうな敵さんがいっぱい～っ！？\nこーなったら、ウルトラとっておき\nドーナツ！　ちょっと湿気てるけど\n…はい騎士ちゃん、あーんっ♪", "vo_empress_136201_001", 389, 1, 0, 5, "", 136201, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_136201_002", "ナーナ", 1, "ナーナだって頑張れるんだよっ！\n騎士ちゃんに、そう教わったもん！\nだから、すごく怖いけど…でもっ…\nナーナ、逃げたりしないよぉっ！", "vo_empress_136201_002", 390, 1, 0, 5, "", 136201, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_136201_003", "ナーナ", 2, "うぅ…あ、足が震えてきちゃった…\nでも動かなきゃ、戦わなきゃっ…\nわかってるのに、でもでもぉ…\nうえぇぇん、やっぱり怖いぃぃ！", "vo_empress_136201_003", 391, 1, 0, 5, "", 136201, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_136201_004", "ナーナ", 3, "今のナーナはよわよわウサギじゃ\nないんだよ。騎士ちゃんのためなら\nどんな敵さんだってやっつけちゃう\nつよつよウサギなんだから！", "vo_empress_136201_004", 392, 1, 136201, 5, "", 136202, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (10000, "vo_empress_136901_001", "ルルィ", 4001, "リーザ姉しゃまが裏切ったなんて\nあたち、信じたくないでしゅ…！\nだから直接聞きにいきましゅ\n吸盤ぜんぶで捕まえてでも…！", "vo_empress_136901_001", 393, 1, 0, 3, 1, 136903, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_136901_002", "ルルィ", 1, "姫姉しゃまも騎士しゃんも\nみなしゃん戦ってるんでしゅ\nあたちだって負けましぇん！\n一生懸命がんばりましゅ～！", "vo_empress_136901_002", 394, 1, 0, 5, "", 136901, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_136901_003", "ルルィ", 2, "あ、あの方、こわいでしゅ…！\n丸呑みにされちゃいそうでしゅっ\nうじゅ…がんばりたいでしゅが…\n震えが止まらないでしゅ…！", "vo_empress_136901_003", 395, 1, 0, 5, "", 136903, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_136901_004", "ルルィ", 3, "あたちは強くないでしゅけど\n騎士しゃんとの約束がありましゅ\nだから誰にも負けましぇん！\nいっちょに、守りましゅよ！", "vo_empress_136901_004", 396, 1, 136901, 5, "", 136902, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_139501_001", "リリ", 1, "これから挑む敵がどれだけ強いと\nしても、勇往邁進していきます\nですからこの戦いでも、兄様の\nおそばで戦わせてくださいませ", "vo_empress_139501_001", 397, 1, 0, 5, "", 139501, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (10000, "vo_empress_139501_002", "リリ", 4002, "幻境竜后の手先、アルシャト…！\nリアさんやヴルム様を陥れた貴方を\n決して許す訳には参りません！\n不倶戴天─ここで成敗致します！", "vo_empress_139501_002", 398, 1, 0, 3, 1, 139503, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_139501_003", "リリ", 2, "幻境竜后の力…これほどまでに\n強力無比だとは…で、ですが…\n何があろうとわたくしは兄様を\nお守りします…命に代えても、必ず", "vo_empress_139501_003", 399, 1, 0, 5, "", 139503, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_139501_004", "リリ", 3, "兄様への想いと、重ねてきた大切な\n時間が、たくさんの勇気と限界を\n超える奇跡をくれました。全ての人\nを救うため、参りましょう兄様…！", "vo_empress_139501_004", 400, 1, 125801, 5, "", 139502, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_139601_001", "クリア", 1, "お兄さん、もし怪我しちゃっても\nすぐに治癒しますからご安心を！\nわたし決めましたから…もう二度と\n自分自身から逃げないって…！", "vo_empress_139601_001", 401, 1, 0, 5, "", 139603, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (10000, "vo_empress_139601_002", "クリア", 4002, "…アルシャトさん…\n謝ったって許してあげませんよ？\nあなたの前では、わたしちょっと\nいい子じゃいられませんから…っ！", "vo_empress_139601_002", 402, 1, 0, 3, 1, 139603, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_139601_003", "クリア", 2, "うぅっ…これが本気の幻境竜后…！\n…こんなの勝てっこありませんよ…\n…せめてお兄さんだけでも…なんて\n最後まで…諦めませんからっ…！", "vo_empress_139601_003", 403, 1, 0, 5, "", 139603, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_139601_004", "クリア", 3, "お兄さんの気持ちが胸に溢れて…\nあ、えへへ…なんだか視界が\n滲んできちゃいました…♪\nわたしはもう、負けませんよ…っ！", "vo_empress_139601_004", 404, 1, 126001, 5, "", 139601, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_139701_001", "プレシア", 1, "てき、いっぱい、しかも、つよすぎ\nけど、まけないよ\nお兄のほっぺ、たべて\nふるぱわー", "vo_empress_139701_001", 405, 1, 0, 5, "", 139701, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_139701_002", "プレシア", 1, "ん\nまだまだ、いける\nお兄、パパ、なかま、いる\nむしゃぶるい", "vo_empress_139701_002", 406, 1, 0, 5, "", 139701, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_139701_003", "プレシア", 2, "しょうり、みえない\nせいぎ、まもれない\nそんなの、いや\nあきらめないよ、さいごまで", "vo_empress_139701_003", 407, 1, 0, 5, "", 139703, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_139701_004", "プレシア", 3, "て、つなぐ\nせいめいりょく、たかまる\nぜったいしょうり！", "vo_empress_139701_004", 408, 1, 126101, 5, "", 139702, 4);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES ("", "vo_empress_140301_004", "ティア", 3, "七冠、幻境竜后──LoAの開発者\nあんたにコワいコト教えてあげるわ\n些細なバグと思って放置したら\nゲームを壊すこともあるってね…♪", "vo_empress_140301_004", 409, 1, 140301, 5, "", 140301, 4);
